(window.KOTOBA_HK=window.KOTOBA_HK||{})[29]={"n":29,"S":[{"id":"l29a","ti":[[["笛吹き","ふえふき"],["男","おとこ"],["と","と"],["帰ってきた","かえってきた","帰る",84],["子どもたち","こどもたち"]]],"tt":{"az":"Tütəkçi və geri qayıdan uşaqlar","en":"The Piper and the Children Who Came Home","ru":"Дудочник и дети, вернувшиеся домой"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["ある","ある","ある(連体詞)"],["町","まち"],["に","に"],["、"],["ねずみ","ねずみ"],["が","が"]],[["たくさん","たくさん"]],[["いました","いました","いる",2],["。"],["ねずみ","ねずみ"],["は","は"]],[["パン","パン"],["を","を"]],[["食べたり","たべたり","食べる",41],["、"],["家","いえ"],["の","の"]],[["中","なか"],["を","を"]],[["走ったり","はしったり","走る",41]],[["しました","しました","する",2],["。"],["町","まち"],["の","の"]],[["人たち","ひとたち"],["は","は"],["、"],["ねずみ","ねずみ"],["が","が"]],[["多","おお","多い"],["すぎて","すぎて","すぎる",3],["、"],["毎日","まいにち"]],[["困って","こまって","困る",3]],[["いました","いました","いる",2],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, bir şəhərdə çoxlu siçan yaşayırdı. Siçanlar çörəkləri yeyir, evlərin içində qaçışırdılar. Şəhər sakinləri siçanların həddindən artıq çox olmasına görə hər gün əziyyət çəkirdilər.","en":"Once upon a time, there was a town full of mice. The mice ate bread and ran around inside people's houses. There were far too many mice, and the townspeople were troubled every day.","ru":"Давным-давно в одном городе было очень много мышей. Мыши ели хлеб и бегали по домам. Мышей стало слишком много, и жители каждый день мучились из-за них."}},{"t":[[["ある日","あるひ"],["、"],["青い","あおい"]],[["帽子","ぼうし"],["を","を"]],[["かぶった","かぶった","かぶる",0]],[["男","おとこ"],["が","が"]],[["町","まち"],["へ","へ"]],[["来ました","きました","来る",2],["。"],["男","おとこ"],["は","は"]],[["笛","ふえ"],["を","を"]],[["持って","もって","持つ",3]],[["いました","いました","いる",2],["。"],["「"],["この","この"]],[["笛","ふえ"],["で","で","だ"]],[["ねずみ","ねずみ"],["を","を"]],[["町","まち"],["の","の"]],[["外","そと"],["へ","へ"]],[["連れて","つれて","連れる",3]],[["行きましょう","いきましょう","行く",20],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["男","おとこ"],["は","は"]],[["笛","ふえ"],["を","を"]],[["吹きながら","ふきながら","吹く",43],["、"],["ゆっくり","ゆっくり"]],[["歩き","あるき","歩く",10],["始めました","はじめました","始める",2],["。"]]],"tr":{"az":"Bir gün şəhərə göy papaqlı bir kişi gəldi. Onun əlində tütək var idi. «Bu tütəklə siçanları şəhərdən çıxararam», – dedi. Kişi tütək çala-çala yavaş-yavaş yeriməyə başladı.","en":"One day, a man wearing a blue hat came to town. He carried a flute. “I will lead the mice out of town with this flute,” he said. He began walking slowly while playing it.","ru":"Однажды в город пришёл человек в синей шляпе. У него была дудочка. «С помощью этой дудочки я уведу мышей из города», – сказал он. И он начал медленно идти, играя на дудочке."}},{"t":[[["する","する","する",5],["と","と"],["、"],["ねずみたち","ねずみたち"],["が","が"]],[["家","いえ"],["から","から"]],[["出てきました","でてきました","出る",23],["。"],["男","おとこ"],["の","の"]],[["後ろ","うしろ"],["を","を"]],[["歩き","あるき","歩く",10],["続けて","つづけて","続ける",3],["、"],["みんな","みんな"]],[["川","かわ"],["の","の"]],[["向こう","むこう"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["町","まち"],["は","は"]],[["静かに","しずかに","静か",8]],[["なりました","なりました","なる",2],["。"],["町","まち"],["の","の"]],[["人たち","ひとたち"],["は","は"]],[["喜びました","よろこびました","喜ぶ",2],["が","が"],["、"],["男","おとこ"],["と","と"],["の","の"]],[["約束","やくそく"],["を","を"]],[["忘れて","わすれて","忘れる",3],["、"],["お金","おかね"],["を","を"]],[["払いませんでした","はらいませんでした","払う",4],["。"]]],"tr":{"az":"Elə bu zaman siçanlar evlərdən çıxmağa başladılar. Kişinin arxasınca gedə-gedə hamısı çayın o biri tərəfinə keçdi. Şəhər sakitləşdi. Sakinlər sevindilər, amma kişi ilə verdikləri sözü unudub ona pul ödəmədilər.","en":"Then the mice came out of the houses. They kept following the man until they all crossed to the other side of the river. The town became quiet. The townspeople were happy, but they forgot their promise to the man and did not pay him.","ru":"Тут мыши начали выходить из домов. Они продолжали идти за человеком и все перебрались на другой берег реки. В городе стало тихо. Жители обрадовались, но забыли своё обещание и не заплатили ему."}},{"t":[[["次","つぎ"],["の","の"]],[["朝","あさ"],["、"],["男","おとこ"],["は","は"]],[["また","また"]],[["笛","ふえ"],["を","を"]],[["吹き","ふき","吹く",10],["始めました","はじめました","始める",2],["。"],["今度","こんど"],["は","は"]],[["子どもたち","こどもたち"],["が","が"]],[["歌いながら","うたいながら","歌う",43],["、"],["男","おとこ"],["の","の"]],[["後ろ","うしろ"],["を","を"]],[["歩き","あるき","歩く",10],["出しました","だしました","出す",2],["。"],["笛","ふえ"],["の","の"]],[["音","おと"],["は","は"]],[["きれい","きれい"],["だ","だ","です"],["し","し"],["、"],["楽しい","たのしい"],["し","し"],["、"],["子どもたち","こどもたち"],["は","は"]],[["夢中に","むちゅうに","夢中",8]],[["なりました","なりました","なる",2],["。"],["遊んでいる","あそんでいる","遊ぶ",45]],[["うち","うち"],["に","に"],["、"],["みんな","みんな"]],[["町","まち"],["から","から"]],[["遠く","とおく","遠い"]],[["離れた","はなれた","離れる",0]],[["花畑","はなばたけ"],["へ","へ"]],[["来ました","きました","来る",2],["。"]]],"tr":{"az":"Ertəsi səhər kişi yenə tütək çalmağa başladı. Bu dəfə uşaqlar mahnı oxuya-oxuya onun arxasınca getməyə başladılar. Tütəyin səsi həm gözəl, həm də şən idi və uşaqlar musiqiyə valeh oldular. Oynaya-oynaya şəhərdən uzaqdakı çiçək tarlasına gəlib çıxdılar.","en":"The next morning, the man began playing his flute again. This time, the children started following him while singing. The flute sounded beautiful and cheerful, and the children were enchanted. While playing, they reached a flower field far from town.","ru":"На следующее утро человек снова заиграл на дудочке. На этот раз дети, напевая песни, пошли за ним. Звуки дудочки были и красивыми, и весёлыми, поэтому дети заслушались. Пока они играли, все оказались на цветочном лугу далеко от города."}},{"t":[[["町","まち"],["で","で"],["は","は"],["、"],["お母さんたち","おかあさんたち"],["が","が"]],[["子ども","こども"],["を","を"]],[["探し","さがし","探す",10],["始めました","はじめました","始める",2],["。"],["「"],["子どもたち","こどもたち"],["は","は"]],[["どこ","どこ"],["です","です"],["か","か"],["」"],["と","と"]],[["泣きながら","なきながら","泣く",43]],[["聞きました","ききました","聞く",2],["。"],["町長","ちょうちょう"],["は","は"],["「"],["約束","やくそく"],["を","を"]],[["守らなかった","まもらなかった","守る",22]],[["私たち","わたしたち"],["が","が"]],[["悪かった","わるかった","悪い",0],["です","です"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["町","まち"],["の","の"]],[["人たち","ひとたち"],["は","は"]],[["お金","おかね"],["と","と"]],[["パン","パン"],["を","を"]],[["持って","もって","持つ",3],["、"],["花畑","はなばたけ"],["へ","へ"]],[["急ぎました","いそぎました","急ぐ",2],["。"]]],"tr":{"az":"Şəhərdə analar uşaqlarını axtarmağa başladılar. «Uşaqlar haradadır?» – deyə ağlaya-ağlaya soruşurdular. Şəhər başçısı «Sözümüzü tutmayan biz idik, səhv etdik», – dedi. Şəhər sakinləri pul və çörək götürüb tələsik çiçək tarlasına yollandılar.","en":"Back in town, the mothers began searching for their children. “Where are the children?” they asked through tears. The mayor said, “We were wrong not to keep our promise.” The townspeople hurried to the flower field with money and bread.","ru":"В городе матери начали искать своих детей. «Где наши дети?» – спрашивали они сквозь слёзы. Мэр сказал: «Мы были неправы, когда не сдержали обещание». Жители взяли деньги и хлеб и поспешили на цветочный луг."}},{"t":[[["花畑","はなばたけ"],["で","で"],["は","は"],["、"],["子どもたち","こどもたち"],["が","が"]],[["花","はな"],["の","の"]],[["冠","かんむり"],["を","を"]],[["作っている","つくっている","作る",26]],[["ところ","ところ"],["でした","でした","です",9],["。"],["男","おとこ"],["は","は"]],[["木","き"],["の","の"]],[["下","した"],["で","で","だ"]],[["休んでいました","やすんでいました","休む",31],["。"],["町長","ちょうちょう"],["は","は"]],[["お金","おかね"],["を","を"]],[["渡して","わたして","渡す",3],["、"],["笛","ふえ"],["の","の"]],[["吹き方","ふきかた"],["を","を"]],[["教えて","おしえて","教える",3]],[["ください","ください","くださる",10],["と","と"]],[["頼みました","たのみました","頼む",2],["。"],["男","おとこ"],["は","は"],["「"],["約束","やくそく"],["は","は"]],[["大切","たいせつ"],["です","です"],["よ","よ"],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Çiçək tarlasında uşaqlar həmin an çiçəklərdən çələng düzəldirdilər. Kişi ağacın altında dincəlirdi. Şəhər başçısı pulu verdi və tütək çalmağın qaydasını öyrətməsini xahiş etdi. Kişi «Verdiyiniz söz çox vacibdir», – deyib gülümsədi.","en":"In the flower field, the children were just making flower crowns. The man was resting under a tree. The mayor handed him the money and asked him to teach them how to play the flute. “Promises are important,” the man said with a smile.","ru":"На цветочном лугу дети как раз плели венки из цветов. Человек отдыхал под деревом. Мэр отдал ему деньги и попросил научить жителей играть на дудочке. «Обещания нужно выполнять», – сказал человек с улыбкой."}},{"t":[[["子どもたち","こどもたち"],["は","は"]],[["町","まち"],["へ","へ"]],[["帰った","かえった","帰る",0]],[["ばかり","ばかり"],["で","で","だ"],["、"],["まだ","まだ"]],[["少し","すこし"]],[["疲れて","つかれて","疲れる",3]],[["いました","いました","いる",2],["。"],["でも","でも"],["、"],["みんな","みんな"]],[["元気","げんき"],["だ","だ","です"],["し","し"],["、"],["けが","けが"],["も","も"]],[["ないし","ないし"],["、"],["お母さんたち","おかあさんたち"],["は","は"]],[["安心","あんしん"],["しました","しました","する",2],["。"],["男","おとこ"],["は","は"]],[["子どもたち","こどもたち"],["に","に"]],[["簡単な","かんたんな","簡単",1]],[["笛","ふえ"],["の","の"]],[["吹き方","ふきかた"],["を","を"]],[["教えました","おしえました","教える",2],["。"],["子どもたち","こどもたち"],["は","は"]],[["練習","れんしゅう"],["を","を"]],[["始めました","はじめました","始める",2],["が","が"],["、"],["最初","さいしょ"],["は","は"]],[["音","おと"],["を","を"]],[["出しにくかった","だしにくかった","出す",85],["です","です"],["。"]]],"tr":{"az":"Uşaqlar şəhərə təzəcə qayıtmışdılar və hələ bir az yorğun idilər. Amma hamısı sağlam idi, heç biri xəsarət almamışdı və analar rahatlandılar. Kişi uşaqlara tütək çalmağın sadə üsulunu öyrətdi. Uşaqlar məşqə başladılar, amma əvvəlcə tütəkdən səs çıxarmaq çətin idi.","en":"The children had just returned to town and were still a little tired. But they were all well and none were hurt, so their mothers felt relieved. The man taught the children a simple way to play the flute. They began practicing, but making a sound was difficult at first.","ru":"Дети только что вернулись в город и ещё немного устали. Но все были здоровы и никто не пострадал, поэтому матери успокоились. Человек показал детям простой способ игры на дудочке. Дети начали заниматься, но сначала им было трудно извлечь звук."}},{"t":[[["その","その"]],[["夜","よる"],["、"],["町","まち"],["で","で","だ"]],[["小さな","ちいさな"]],[["音楽","おんがく"],["会","かい"],["が","が"]],[["ありました","ありました","ある",2],["。"],["子どもたち","こどもたち"],["は","は"]],[["笛","ふえ"],["を","を"]],[["吹き","ふき","吹く",10],["終わる","おわる","終わる",5],["と","と"],["、"],["大きな","おおきな"]],[["声","こえ"],["で","で","だ"]],[["笑い","わらい","笑う",10],["出しました","だしました","出す",2],["。"],["ある","ある","ある(連体詞)"]],[["子","こ"],["の","の"]],[["笛","ふえ"],["から","から"],["は","は"],["「"],["プー","プー"],["！"],["」"],["と","と"]],[["変な","へんな","変",1]],[["音","おと"],["が","が"]],[["出ました","でました","出る",2],["。"],["でも","でも"],["、"],["その","その"]],[["音","おと"],["が","が"]],[["いちばん","いちばん"]],[["おもしろくて","おもしろくて","おもしろい",3],["、"],["町","まち"],["の","の"]],[["人たち","ひとたち"],["は","は"]],[["笑いながら","わらいながら","笑う",43]],[["拍手","はくしゅ"],["しました","しました","する",2],["。"],["それから","それから"]],[["この","この"]],[["町","まち"],["で","で"],["は","は"],["、"],["約束","やくそく"],["を","を"]],[["守る","まもる","守る",5],["こと","こと"],["と","と"],["、"],["楽しく","たのしく","楽しい"]],[["音楽","おんがく"],["を","を"]],[["練習","れんしゅう"],["する","する","する",5],["こと","こと"],["が","が"]],[["大切に","たいせつに","大切",8]],[["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Həmin axşam şəhərdə kiçik bir musiqi tədbiri keçirildi. Uşaqlar tütək çalmağı bitirən kimi ucadan gülməyə başladılar. Bir uşağın tütəyindən qəribə «Puu!» səsi çıxdı. Amma ən gülməlisi elə o səs idi və şəhər sakinləri gülə-gülə əl çaldılar. O gündən sonra bu şəhərdə sözə əməl etməyə və musiqini sevə-sevə öyrənməyə böyük əhəmiyyət verildi.","en":"That evening, the town held a little concert. As soon as the children finished playing their flutes, they burst into laughter. One child's flute made a strange “Poo!” sound. But it was the funniest sound of all, and the townspeople clapped while laughing. From then on, the town valued keeping promises and practicing music with joy.","ru":"В тот вечер в городе устроили маленький концерт. Закончив играть на дудочках, дети громко рассмеялись. У одного ребёнка дудочка издала странное «Пу-у!». Но этот звук оказался самым забавным, и жители хлопали, смеясь. С тех пор в городе стали особенно ценить верность обещаниям и радостные занятия музыкой."}}]},{"id":"l29b","ti":[[["星","ほし"],["の","の"],["ステージ","ステージ"],["と","と"],["三人","さんにん"],["の","の"],["約束","やくそく"]]],"tt":{"az":"Ulduzlu səhnə və üç dostun vədi","en":"The Starry Stage and the Three Friends' Promise","ru":"Звёздная сцена и обещание трёх друзей"},"P":[{"t":[[["海","うみ"],["の","の"]],[["近く","ちかく"],["の","の"]],[["小さな","ちいさな"]],[["町","まち"],["に","に"],["、"],["三人","さんにん"],["の","の"]],[["女の子","おんなのこ"],["が","が"]],[["いました","いました","いる",2],["。"],["名前","なまえ"],["は","は"]],[["ミオ","ミオ"],["、"],["ハナ","ハナ"],["、"],["ユキ","ユキ"],["でした","でした","です",9],["。"],["三人","さんにん"],["は","は"]],[["歌","うた"],["が","が"]],[["好き","すき"],["だ","だ","です"],["し","し"],["、"],["ダンス","ダンス"],["も","も"]],[["好き","すき"],["だ","だ","です"],["し","し"],["、"],["いつ","いつ"],["か","か"]],[["アイドル","アイドル"],["に","に"]],[["なりたい","なりたい","なる",30],["と","と"]],[["思って","おもって","思う",3]],[["いました","いました","いる",2],["。"],["ある","ある","ある(連体詞)"]],[["日","ひ"],["、"],["初めて","はじめて"],["の","の"]],[["コンサート","コンサート"],["が","が"]],[["決まりました","きまりました","決まる",2],["。"]]],"tr":{"az":"Dəniz kənarındakı balaca şəhərdə üç qız yaşayırdı. Onların adları Mio, Hana və Yuki idi. Üçü də həm mahnı oxumağı, həm də rəqs etməyi sevirdi və bir gün idol müğənni olmaq istəyirdilər. Bir gün onların ilk konsertinin tarixi müəyyənləşdi.","en":"In a small town near the sea lived three girls named Mio, Hana, and Yuki. All three loved singing and dancing, and dreamed of becoming idols someday. One day, the date of their very first concert was decided.","ru":"В маленьком приморском городке жили три девочки: Мио, Хана и Юки. Все трое любили петь и танцевать и мечтали однажды стать айдолами. И вот однажды была назначена дата их первого концерта."}},{"t":[[["三人","さんにん"],["は","は"]],[["毎日","まいにち"],["、"],["学校","がっこう"],["が","が"]],[["終わって","おわって","終わる",3],["から","から"]],[["練習","れんしゅう"],["しました","しました","する",2],["。"],["ミオ","ミオ"],["は","は"]],[["歌いながら","うたいながら","歌う",43]],[["踊り","おどり","踊る",10],["、"],["ハナ","ハナ"],["は","は"]],[["音楽","おんがく"],["を","を"]],[["聞きながら","ききながら","聞く",43]],[["動き","うごき"],["を","を"]],[["覚えました","おぼえました","覚える",2],["。"],["ユキ","ユキ"],["は","は"]],[["鏡","かがみ"],["を","を"]],[["見ながら","みながら","見る",43],["、"],["手","て"],["の","の"]],[["動かし方","うごかしかた"],["を","を"]],[["練習","れんしゅう"],["しました","しました","する",2],["。"],["新しい","あたらしい"]],[["歌","うた"],["は","は"]],[["覚えやすかった","おぼえやすかった","覚える",86],["です","です"],["が","が"],["、"],["ダンス","ダンス"],["は","は"]],[["少し","すこし"]],[["難しかった","むずかしかった","難しい",0],["です","です"],["。"]]],"tr":{"az":"Üç qız hər gün dərsdən sonra məşq edirdi. Mio oxuya-oxuya rəqs edir, Hana musiqi dinləyə-dinləyə hərəkətləri əzbərləyirdi. Yuki isə güzgüyə baxaraq əl hərəkətlərini məşq edirdi. Yeni mahnını yadda saxlamaq asan idi, amma rəqs bir az çətin idi.","en":"Every day after school, the three girls practiced. Mio danced while singing, and Hana memorized the moves while listening to music. Yuki practiced her hand movements while looking in the mirror. The new song was easy to remember, but the dance was a little difficult.","ru":"Каждый день после школы девочки репетировали. Мио танцевала и пела, а Хана запоминала движения, слушая музыку. Юки тренировала движения рук перед зеркалом. Новую песню было легко запомнить, но танец оказался немного сложным."}},{"t":[[["コンサート","コンサート"],["の","の"]],[["三日","みっか"]],[["前","まえ"],["、"],["ミオ","ミオ"],["は","は"]],[["練習","れんしゅう"],["し","し","する",10],["すぎました","すぎました","すぎる",2],["。"],["歌い","うたい","歌う",10],["続けている","つづけている","続ける",26]],[["うち","うち"],["に","に"],["、"],["声","こえ"],["が","が"]],[["小さく","ちいさく","小さい"]],[["なりました","なりました","なる",2],["。"],["「"],["声","こえ"],["が","が"]],[["出にくい","でにくい","出る",87],["です","です"],["」"],["と","と"]],[["ミオ","ミオ"],["は","は"]],[["言いました","いいました","言う",2],["。"],["ハナ","ハナ"],["も","も"]],[["足","あし"],["が","が"]],[["痛く","いたく","痛い"],["なった","なった","なる",0]],[["ばかり","ばかり"],["でした","でした","です",9],["。"],["三人","さんにん"],["は","は"]],[["とても","とても"]],[["心配","しんぱい"],["しました","しました","する",2],["。"]]],"tr":{"az":"Konsertə üç gün qalmış Mio həddindən artıq məşq etdi. Uzun müddət oxuduqca səsi zəiflədi. «Səsimi çıxarmaq çətinləşib», – dedi Mio. Hananın da ayağı yenicə ağrımağa başlamışdı. Üçü də çox narahat oldu.","en":"Three days before the concert, Mio practiced too much. As she kept singing, her voice grew weak. “It's hard to get my voice out,” she said. Hana's foot had also just started hurting. All three girls became very worried.","ru":"За три дня до концерта Мио слишком много репетировала. Пока она продолжала петь, её голос ослабел. «Мне трудно петь», – сказала Мио. У Ханы тоже только что заболела нога. Все три девочки сильно забеспокоились."}},{"t":[[["その","その"]],[["とき","とき"],["、"],["先生","せんせい"],["が","が"]],[["練習室","れんしゅうしつ"],["に","に"]],[["入ってきました","はいってきました","入る",23],["。"],["三人","さんにん"],["は","は"]],[["新しい","あたらしい"]],[["ダンス","ダンス"],["を","を"]],[["始める","はじめる","始める",5]],[["ところ","ところ"],["でした","でした","です",9],["。"],["先生","せんせい"],["は","は"],["「"],["練習","れんしゅう"],["も","も"]],[["大切","たいせつ"],["です","です"],["が","が"],["、"],["休む","やすむ","休む",5],["こと","こと"],["も","も"]],[["大切","たいせつ"],["です","です"],["よ","よ"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["疲れにくい","つかれにくい","疲れる",87]],[["踊り方","おどりかた"],["と","と"],["、"],["声","こえ"],["を","を"]],[["大切に","たいせつに","大切",8]],[["する","する","する",5]],[["方法","ほうほう"],["を","を"]],[["教えました","おしえました","教える",2],["。"]]],"tr":{"az":"Elə həmin vaxt müəllim məşq otağına girdi. Üç qız yeni rəqsi məşq etməyə hazırlaşırdı. Müəllim «Məşq etmək vacibdir, amma dincəlmək də vacibdir», – dedi. Sonra onlara az yorucu rəqs üsulunu və səslərini necə qorumalı olduqlarını öyrətdi.","en":"Just then, their teacher entered the practice room. The girls were about to start a new dance. “Practice is important, but resting is important too,” the teacher said. Then the teacher showed them a less tiring way to dance and how to take care of their voices.","ru":"В этот момент учитель вошёл в репетиционную комнату. Девочки как раз собирались начать новый танец. «Репетиции важны, но отдых тоже важен», – сказал учитель. Затем он показал им, как танцевать, чтобы меньше уставать, и как беречь голос."}},{"t":[[["次","つぎ"],["の","の"]],[["日","ひ"],["、"],["三人","さんにん"],["は","は"]],[["ゆっくり","ゆっくり"]],[["練習","れんしゅう"],["を","を"]],[["始めました","はじめました","始める",2],["。"],["水","みず"],["を","を"]],[["飲みながら","のみながら","飲む",43]],[["休んだり","やすんだり","休む",42],["、"],["短い","みじかい"]],[["歌","うた"],["を","を"]],[["歌ったり","うたったり","歌う",41]],[["しました","しました","する",2],["。"],["明るい","あかるい"]],[["部屋","へや"],["だ","だ","です"],["し","し"],["、"],["先生","せんせい"],["も","も"]],[["親切","しんせつ"],["だ","だ","です"],["し","し"],["、"],["みんな","みんな"],["の","の"]],[["気持ち","きもち"],["は","は"]],[["少し","すこし"],["ずつ","ずつ"]],[["軽く","かるく","軽い"]],[["なりました","なりました","なる",2],["。"],["夕方","ゆうがた"],["まで","まで"],["に","に"],["、"],["三人","さんにん"],["は","は"]],[["最後","さいご"],["の","の"]],[["ダンス","ダンス"],["を","を"]],[["覚え","おぼえ","覚える",10],["終わりました","おわりました","終わる",2],["。"]]],"tr":{"az":"Ertəsi gün qızlar sakit tempdə məşqə başladılar. Su içib dincəlir, qısa mahnılar oxuyurdular. Otaq işıqlı, müəllim də mehriban idi və hamının əhvalı yavaş-yavaş düzəldi. Axşama qədər üçü də son rəqsi tam öyrəndi.","en":"The next day, the girls began practicing at a gentle pace. They took breaks while drinking water and sang short songs. The room was bright and the teacher was kind, so everyone gradually felt better. By evening, they had finished learning their final dance.","ru":"На следующий день девочки начали репетировать в спокойном темпе. Они отдыхали, пили воду и пели короткие песни. Комната была светлой, учитель был добрым, и настроение у всех постепенно улучшилось. К вечеру они закончили разучивать последний танец."}},{"t":[[["とうとう","とうとう"]],[["コンサート","コンサート"],["の","の"]],[["日","ひ"],["に","に"]],[["なりました","なりました","なる",2],["。"],["三人","さんにん"],["は","は"]],[["きれいな","きれいな","きれい",1]],[["服","ふく"],["を","を"]],[["着た","きた","着る",0]],[["ばかり","ばかり"],["で","で","だ"],["、"],["まだ","まだ"]],[["少し","すこし"]],[["緊張","きんちょう"],["して","して","する",3]],[["いました","いました","いる",2],["。"],["ユキ","ユキ"],["は","は"],["「"],["お客さん","おきゃくさん"],["が","が"]],[["多","おお","多い"],["すぎたら","すぎたら","すぎる",44],["、"],["どう","どう"],["しましょう","しましょう","する",20],["」"],["と","と"]],[["小さな","ちいさな"]],[["声","こえ"],["で","で","だ"]],[["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["音楽","おんがく"],["が","が"]],[["始まる","はじまる","始まる",5],["と","と"],["、"],["三人","さんにん"],["は","は"]],[["笑顔","えがお"],["で","で","だ"]],[["歌い出しました","うたいだしました","歌い出す",2],["。"]]],"tr":{"az":"Nəhayət, konsert günü gəlib çatdı. Qızlar gözəl səhnə geyimlərini təzəcə geyinmişdilər və hələ bir az həyəcanlı idilər. Yuki astadan «Tamaşaçı həddindən artıq çox olsa, nə edərik?» – dedi. Amma musiqi başlayan kimi üçü də gülümsəyərək oxumağa başladı.","en":"At last, concert day arrived. The girls had just put on their beautiful costumes and were still a little nervous. “What if there are too many people?” Yuki whispered. But when the music began, all three burst into song with smiles on their faces.","ru":"Наконец наступил день концерта. Девочки только что надели красивые костюмы и ещё немного волновались. «А что, если зрителей будет слишком много?» – тихо спросила Юки. Но когда заиграла музыка, все трое с улыбками запели."}},{"t":[[["ところ","ところ"],["が","が"],["、"],["二つ目","ふたつめ"],["の","の"]],[["歌","うた"],["の","の"]],[["とき","とき"],["、"],["音楽","おんがく"],["が","が"]],[["急","きゅう"],["に","に","だ"]],[["止まりました","とまりました","止まる",2],["。"],["三人","さんにん"],["は","は"]],[["びっくり","びっくり"],["しました","しました","する",2],["が","が"],["、"],["ミオ","ミオ"],["が","が"]],[["手","て"],["を","を"]],[["たたき","たたき","たたく",10],["始めました","はじめました","始める",2],["。"],["ハナ","ハナ"],["と","と"]],[["ユキ","ユキ"],["も","も"]],[["手","て"],["を","を"]],[["たたきながら","たたきながら","たたく",43]],[["歌い","うたい","歌う",10],["続けました","つづけました","続ける",2],["。"],["お客さん","おきゃくさん"],["も","も"]],[["いっしょ","いっしょ"],["に","に"]],[["歌い出して","うたいだして","歌い出す",3],["、"],["会場","かいじょう"],["は","は"]],[["大きな","おおきな"]],[["声","こえ"],["で","で","だ"]],[["いっぱい","いっぱい"],["に","に","だ"]],[["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Ancaq ikinci mahnı zamanı musiqi qəfil dayandı. Üç qız təəccübləndi, amma Mio əl çalmağa başladı. Hana ilə Yuki də əl çala-çala oxumağa davam etdilər. Tamaşaçılar da onlara qoşulub oxumağa başladılar və bütün zal mahnı səsləri ilə doldu.","en":"But during the second song, the music suddenly stopped. The girls were startled, but Mio began clapping her hands. Hana and Yuki kept singing while clapping too. The audience joined in, and the hall filled with loud singing.","ru":"Но во время второй песни музыка внезапно остановилась. Девочки испугались, однако Мио начала хлопать в ладоши. Хана и Юки тоже продолжили петь и хлопать. Зрители запели вместе с ними, и весь зал наполнился громкими голосами."}},{"t":[[["三人","さんにん"],["が","が"]],[["最後","さいご"],["の","の"]],[["歌","うた"],["を","を"]],[["歌い","うたい","歌う",10],["終わる","おわる","終わる",5],["と","と"],["、"],["大きな","おおきな"]],[["拍手","はくしゅ"],["が","が"]],[["聞こえました","きこえました","聞こえる",2],["。"],["先生","せんせい"],["は","は"]],[["泣きながら","なきながら","泣く",43]],[["笑って","わらって","笑う",3]],[["いました","いました","いる",2],["。"],["「"],["すばらしい","すばらしい"]],[["コンサート","コンサート"],["でした","でした","です",9],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["三人","さんにん"],["は","は"]],[["ステージ","ステージ"],["の","の"]],[["上","うえ"],["で","で"]],[["手","て"],["を","を"]],[["つなぎました","つなぎました","つなぐ",2],["。"],["その","その"]],[["夜","よる"],["、"],["星","ほし"],["が","が"]],[["たくさん","たくさん"]],[["見えました","みえました","見える",2],["が","が"],["、"],["三人","さんにん"],["に","に"],["は","は"]],[["お客さん","おきゃくさん"],["の","の"]],[["笑顔","えがお"],["が","が"]],[["いちばん","いちばん"]],[["明るい","あかるい"]],[["星","ほし"],["に","に"]],[["見えました","みえました","見える",2],["。"]]],"tr":{"az":"Üç qız son mahnını bitirəndə gurultulu alqış səsləri eşidildi. Müəllim sevinc göz yaşları içində gülümsəyirdi. «Möhtəşəm konsert idi», – dedi. Qızlar səhnədə əl-ələ tutdular. Həmin gecə göydə çoxlu ulduz görünürdü, amma üç qız üçün tamaşaçıların təbəssümü ən parlaq ulduz idi.","en":"When the girls finished their final song, thunderous applause rang out. Their teacher was smiling through tears. “That was a wonderful concert,” the teacher said. The girls held hands onstage. Many stars shone that night, but to the three girls, the audience's smiles were the brightest stars of all.","ru":"Когда девочки закончили последнюю песню, раздались громкие аплодисменты. Учитель улыбался сквозь слёзы. «Это был замечательный концерт», – сказал он. Девочки взялись за руки на сцене. В ту ночь на небе сияло много звёзд, но для трёх подруг улыбки зрителей были ярче всех звёзд."}}]},{"id":"l29c","ti":[[["おばあさん","おばあさん"],["の","の"],["不思議な","ふしぎな","不思議",1],["買い物","かいもの"],["メモ","メモ"]]],"tt":{"az":"Nənənin sirli alış-veriş siyahısı","en":"Grandma's Mysterious Shopping List","ru":"Загадочный список покупок бабушки"},"P":[{"t":[[["ある","ある","ある(連体詞)"]],[["町","まち"],["に","に"],["、"],["ケン","ケン"],["と","と"],["いう","いう","いう",5]],[["男の子","おとこのこ"],["が","が"]],[["いました","いました","いる",2],["。"],["ケン","ケン"],["は","は"]],[["おばあさん","おばあさん"],["と","と"]],[["いっしょ","いっしょ"],["に","に"]],[["住んで","すんで","住む",13]],[["いました","いました","いる",2],["。"],["おばあさん","おばあさん"],["は","は"]],[["料理","りょうり"],["が","が"]],[["上手","じょうず"],["だ","だ","です"],["し","し"],["、"],["いつ","いつ"],["も","も"]],[["元気","げんき"],["だ","だ","です"],["し","し"],["、"],["町","まち"],["の","の"]],[["人気者","にんきもの"],["でした","でした","です",9],["。"],["ある","ある","ある(連体詞)"]],[["朝","あさ"],["、"],["おばあさん","おばあさん"],["は","は"],["「"],["今日","きょう"],["は","は"]],[["特別な","とくべつな","特別",1]],[["料理","りょうり"],["を","を"]],[["作ります","つくります","作る",11],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Bir şəhərdə Ken adlı bir oğlan yaşayırdı. Ken nənəsi ilə birlikdə qalırdı. Nənəsi həm çox yaxşı yemək bişirirdi, həm də həmişə enerjili idi və şəhərdə hamı onu sevirdi. Bir səhər nənəsi «Bu gün xüsusi yemək hazırlayacağam», – dedi.","en":"In a certain town lived a boy named Ken. He lived with his grandmother. She was a wonderful cook, always full of energy, and loved by everyone in town. One morning, she said, “Today I'm going to make something special.”","ru":"В одном городе жил мальчик по имени Кэн. Он жил вместе с бабушкой. Бабушка прекрасно готовила, всегда была полна сил, и все в городе её любили. Однажды утром она сказала: «Сегодня я приготовлю особенное блюдо»."}},{"t":[[["おばあさん","おばあさん"],["は","は"]],[["紙","かみ"],["に","に"]],[["何","なに"],["か","か"],["を","を"]],[["書きながら","かきながら","書く",43],["、"],["歌","うた"],["を","を"]],[["歌って","うたって","歌う",3]],[["いました","いました","いる",2],["。"],["それから","それから"],["「"],["この","この"]],[["メモ","メモ"],["を","を"]],[["見ながら","みながら","見る",43],["、"],["買い物","かいもの"],["を","を"]],[["してきて","してきて","する",88],["ね","ね"],["」"],["と","と"]],[["ケン","ケン"],["に","に"]],[["言いました","いいました","言う",2],["。"],["ケン","ケン"],["は","は"]],[["学校","がっこう"],["から","から"]],[["帰った","かえった","帰る",0]],[["ばかり","ばかり"],["でした","でした","です",9],["が","が"],["、"],["元気","げんき"],["よく","よく","よい"]],[["出かけました","でかけました","出かける",2],["。"],["紙","かみ"],["に","に"],["は","は"],["「"],["赤い","あかい"]],[["もの","もの"],["、"],["丸い","まりい"]],[["もの","もの"],["、"],["甘い","あまい"]],[["もの","もの"],["」"],["と","と"]],[["書いて","かいて","書く",3]],[["ありました","ありました","ある",2],["。"]]],"tr":{"az":"Nənəsi mahnı oxuya-oxuya kağıza nəsə yazırdı. Sonra Kenə «Bu siyahıya baxa-baxa alış-veriş et, yaxşı?» – dedi. Ken məktəbdən təzəcə qayıtmışdı, amma həvəslə evdən çıxdı. Kağızda «Qırmızı bir şey, yumru bir şey, şirin bir şey» yazılmışdı.","en":"Grandma hummed a song while writing something on a piece of paper. Then she told Ken, “Please go shopping and use this note.” Ken had just come home from school, but he went out cheerfully. The paper said, “Something red, something round, something sweet.”","ru":"Бабушка напевала песню и что-то писала на листке бумаги. Потом сказала Кэну: «Сходи за покупками по этому списку». Кэн только что вернулся из школы, но с радостью отправился в магазин. На бумаге было написано: «Что-нибудь красное, круглое и сладкое»."}},{"t":[[["ケン","ケン"],["は","は"]],[["店","みせ"],["まで","まで"]],[["歩きながら","あるきながら","歩く",43],["、"],["何","なに"],["を","を"]],[["買う","かう","買う",5],["か","か"]],[["考えました","かんがえました","考える",2],["。"],["「"],["赤い","あかい"]],[["もの","もの"],["は","は"]],[["トマト","トマト"],["か","か"],["な","な"],["。"],["丸い","まりい"]],[["もの","もの"],["は","は"]],[["ボール","ボール"],["か","か"],["な","な"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["店","みせ"],["に","に"]],[["着く","つく","着く",5],["と","と"],["、"],["店","みせ"],["の","の"]],[["人","ひと"],["が","が"]],[["品物","しなもの"],["の","の"]],[["選び方","えらびかた"],["を","を"]],[["教えて","おしえて","教える",3]],[["くれました","くれました","くれる",2],["。"],["でも","でも"],["、"],["メモ","メモ"],["の","の"]],[["字","じ"],["は","は"]],[["小さ","ちいさ","小さい"],["すぎて","すぎて","すぎる",3],["、"],["少し","すこし"]],[["読みにくかった","よみにくかった","読む",85],["です","です"],["。"]]],"tr":{"az":"Ken mağazaya tərəf yeriyə-yeriyə nə alacağını düşünürdü. «Qırmızı şey pomidor ola bilər. Yumru şey isə bəlkə topdur», – dedi. Mağazaya çatanda satıcı ona məhsulları necə seçməyi öyrətdi. Amma siyahıdakı yazılar həddindən artıq kiçik idi, ona görə də onları oxumaq bir az çətin idi.","en":"As Ken walked to the shop, he thought about what to buy. “Maybe the red thing is a tomato. Maybe the round thing is a ball,” he said. At the shop, the owner showed him how to choose good products. But the writing on the note was too small and a little hard to read.","ru":"По дороге в магазин Кэн думал, что купить. «Красное – наверное, помидор. Круглое – может быть, мяч», – сказал он. В магазине продавец показал ему, как выбирать товары. Но буквы в записке были слишком маленькими, и читать её было трудно."}},{"t":[[["ケン","ケン"],["は","は"]],[["トマト","トマト"],["と","と"]],[["小さな","ちいさな"]],[["ボール","ボール"],["と","と"]],[["チョコレート","チョコレート"],["を","を"]],[["買いました","かいました","買う",2],["。"],["家","いえ"],["へ","へ"]],[["帰る","かえる","帰る",5]],[["途中","とちゅう"],["、"],["雨","あめ"],["が","が"]],[["降り","ふり","降る",10],["出しました","だしました","出す",2],["。"],["ケン","ケン"],["は","は"]],[["走り","はしり","走る",10],["始めました","はじめました","始める",2],["が","が"],["、"],["道","みち"],["が","が"]],[["滑りやすくて","すべりやすくて","滑る",89],["、"],["ゆっくり","ゆっくり"]],[["歩く","あるく","歩く",5],["こと","こと"],["に","に"]],[["しました","しました","する",2],["。"],["雨","あめ"],["が","が"]],[["強く","つよく","強い"],["なる","なる","なる",5]],[["うち","うち"],["に","に"],["、"],["買った","かった","買う",0]],[["もの","もの"],["を","を"]],[["大切に","たいせつに","大切",8]],[["持って","もって","持つ",3]],[["帰りました","かえりました","帰る",2],["。"]]],"tr":{"az":"Ken pomidor, balaca top və şokolad aldı. Evə qayıdarkən yağış yağmağa başladı. Ken qaçmağa başladı, amma yol sürüşkən olduğuna görə yavaş yeriməyə qərar verdi. Yağış getdikcə güclənirdi, o isə aldıqlarını ehtiyatla evə apardı.","en":"Ken bought a tomato, a small ball, and some chocolate. On his way home, it started raining. He began to run, but the road was slippery, so he decided to walk slowly. As the rain grew heavier, he carefully carried his purchases home.","ru":"Кэн купил помидор, маленький мяч и шоколад. По дороге домой начался дождь. Кэн побежал, но дорога была скользкой, поэтому он решил идти медленно. Дождь усиливался, а мальчик осторожно нёс покупки домой."}},{"t":[[["家","いえ"],["に","に"]],[["着く","つく","着く",5],["と","と"],["、"],["おばあさん","おばあさん"],["は","は"]],[["料理","りょうり"],["を","を"]],[["始める","はじめる","始める",5]],[["ところ","ところ"],["でした","でした","です",9],["。"],["ケン","ケン"],["は","は"]],[["買った","かった","買う",0]],[["もの","もの"],["を","を"]],[["見せました","みせました","見せる",2],["。"],["おばあさん","おばあさん"],["は","は"]],[["トマト","トマト"],["と","と"]],[["チョコレート","チョコレート"],["を","を"]],[["見て","みて","見る",3],["、"],["笑いました","わらいました","笑う",2],["。"],["でも","でも"],["、"],["ボール","ボール"],["を","を"]],[["見た","みた","見る",0]],[["とき","とき"],["、"],["びっくり","びっくり"],["して","して","する",3]],[["笑い","わらい","笑う",10],["出しました","だしました","出す",2],["。"],["「"],["これ","これ"],["は","は"]],[["食べられません","たべられません","食べる",90],["ね","ね"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Evə çatanda nənəsi yemək bişirməyə başlamaq üzrə idi. Ken aldıqlarını ona göstərdi. Nənəsi pomidorla şokoladı görüb gülümsədi. Amma topu görəndə təəccübləndi və qəhqəhə çəkdi. «Bunu yemək olmaz axı», – dedi.","en":"When Ken arrived home, Grandma was just about to start cooking. He showed her what he had bought. She smiled when she saw the tomato and chocolate. But when she saw the ball, she was so surprised that she burst out laughing. “We can't eat this!” she said.","ru":"Когда Кэн вернулся домой, бабушка как раз собиралась начать готовить. Он показал ей покупки. Увидев помидор и шоколад, бабушка улыбнулась. Но когда она заметила мяч, то удивилась и расхохоталась. «Это же нельзя есть!» – сказала она."}},{"t":[[["おばあさん","おばあさん"],["は","は"]],[["本当","ほんとう"],["の","の"]],[["メモ","メモ"],["を","を"]],[["出しました","だしました","出す",2],["。"],["「"],["赤い","あかい"]],[["りんご","りんご"],["、"],["丸い","まりい"]],[["たまご","たまご"],["、"],["甘い","あまい"]],[["さとう","さとう"],["」"],["と","と"]],[["書いて","かいて","書く",3]],[["ありました","ありました","ある",2],["。"],["ケン","ケン"],["は","は"]],[["間違えた","まちがえた","間違える",0],["こと","こと"],["に","に"]],[["気づいて","きづいて","気づく",3],["、"],["顔","かお"],["が","が"]],[["赤く","あかく","赤い"]],[["なりました","なりました","なる",2],["。"],["おばあさん","おばあさん"],["は","は"],["「"],["字","じ"],["を","を"]],[["小さく","ちいさく","小さい"]],[["書き","かき","書く",10],["すぎました","すぎました","すぎる",2],["ね","ね"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["大きな","おおきな"]],[["字","じ"],["で","で","だ"]],[["書く","かく","書く",5]],[["方法","ほうほう"],["を","を"]],[["ケン","ケン"],["に","に"]],[["教えました","おしえました","教える",2],["。"]]],"tr":{"az":"Nənəsi əsl siyahını çıxardı. Orada «Qırmızı alma, yumru yumurta, şirin şəkər» yazılmışdı. Ken səhv etdiyini başa düşüb utandığından qızardı. Nənəsi «Görünür, yazını çox kiçik yazmışam», – dedi. Sonra Kenə böyük hərflərlə necə yazmağı göstərdi.","en":"Grandma took out the real shopping list. It said, “Red apples, round eggs, sweet sugar.” Ken realized his mistake and blushed. “I wrote the letters too small,” Grandma said. Then she showed Ken how to write in large, clear letters.","ru":"Бабушка достала настоящий список покупок. Там было написано: «Красные яблоки, круглые яйца, сладкий сахар». Кэн понял свою ошибку и покраснел. «Я написала слишком мелко», – сказала бабушка. Затем она показала Кэну, как писать крупными буквами."}},{"t":[[["二人","ふたり"],["は","は"]],[["笑いながら","わらいながら","笑う",43],["、"],["もう","もう"]],[["一度","いちど"]],[["買い物","かいもの"],["に","に"]],[["行きました","いきました","行く",2],["。"],["今度","こんど"],["は","は"]],[["大きな","おおきな"]],[["字","じ"],["の","の"]],[["メモ","メモ"],["だ","だ","です"],["し","し"],["、"],["品物","しなもの"],["の","の"]],[["名前","なまえ"],["も","も"]],[["はっきり","はっきり"]],[["書いて","かいて","書く",3]],[["ある","ある","ある",5],["し","し"],["、"],["間違えませんでした","まちがえませんでした","間違える",4],["。"],["家","いえ"],["へ","へ"]],[["帰る","かえる","帰る",5],["と","と"],["、"],["おばあさん","おばあさん"],["は","は"]],[["りんご","りんご"],["の","の"]],[["ケーキ","ケーキ"],["を","を"]],[["作り","つくり","作る",10],["始めました","はじめました","始める",2],["。"],["ケン","ケン"],["は","は"]],[["たまご","たまご"],["を","を"]],[["割りながら","わりながら","割る",43]],[["手伝い","てつだい"],["、"],["ケーキ","ケーキ"],["が","が"]],[["焼ける","やける","焼ける",5],["まで","まで"]],[["歌い","うたい","歌う",10],["続けました","つづけました","続ける",2],["。"]]],"tr":{"az":"İkisi gülə-gülə yenidən alış-verişə getdi. Bu dəfə siyahı böyük hərflərlə yazılmışdı, məhsulların adları da aydın idi, ona görə səhv etmədilər. Evə qayıdanda nənəsi almalı piroq hazırlamağa başladı. Ken yumurtaları sındıraraq ona kömək etdi və piroq bişənə qədər mahnı oxumağa davam etdi.","en":"Laughing together, they went shopping once more. This time, the list had large letters and clearly written names, so they made no mistakes. When they got home, Grandma began making an apple cake. Ken helped by cracking eggs and kept singing until the cake was baked.","ru":"Смеясь, они снова пошли за покупками. На этот раз список был написан крупными буквами, а названия продуктов были понятными, поэтому они ничего не перепутали. Вернувшись домой, бабушка начала готовить яблочный пирог. Кэн помогал разбивать яйца и продолжал петь, пока пирог не испёкся."}},{"t":[[["ケーキ","ケーキ"],["を","を"]],[["作り","つくり","作る",10],["終わる","おわる","終わる",5],["と","と"],["、"],["二人","ふたり"],["は","は"]],[["いっしょ","いっしょ"],["に","に"]],[["食べました","たべました","食べる",2],["。"],["ケン","ケン"],["は","は"],["「"],["今日","きょう"],["の","の"]],[["買い物","かいもの"],["は","は"]],[["おもしろかった","おもしろかった","おもしろい",0],["です","です"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["その","その"]],[["とき","とき"],["、"],["おばあさん","おばあさん"],["は","は"]],[["ボール","ボール"],["を","を"]],[["持ってきました","もってきました","持つ",23],["。"],["「"],["食べ","たべ","食べる",10],["終わった","おわった","終わる",0]],[["ばかり","ばかり"],["です","です"],["が","が"],["、"],["少し","すこし"]],[["遊びましょう","あそびましょう","遊ぶ",20],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["二人","ふたり"],["は","は"]],[["庭","にわ"],["で","で","だ"]],[["ボール","ボール"],["を","を"]],[["投げながら","なげながら","投げる",43]],[["笑いました","わらいました","笑う",2],["。"],["実","じつ"],["は","は"],["、"],["おばあさん","おばあさん"],["も","も"]],[["前","まえ"],["から","から"]],[["ボール","ボール"],["で","で","だ"]],[["遊びたかった","あそびたかった","遊ぶ",21],["の","の"],["でした","でした","です",9],["。"]]],"tr":{"az":"Piroqu hazırlayıb bitirəndən sonra ikisi birlikdə yedilər. Ken «Bugünkü alış-veriş çox maraqlı idi», – dedi. Elə həmin vaxt nənəsi topu gətirdi. «Təzəcə yeməyimizi bitirmişik, amma gəl bir az oynayaq», – dedi. İkisi həyətdə top atıb-tutaraq güldülər. Sən demə, nənəsi də çoxdan top oynamaq istəyirmiş.","en":"When the cake was finished, they ate it together. “Today's shopping was fun,” Ken said. Just then, Grandma brought out the ball. “We've only just finished eating, but let's play a little,” she said. They laughed as they tossed the ball around the garden. As it turned out, Grandma had wanted to play ball for a long time too.","ru":"Когда пирог был готов, они вместе его съели. «Сегодня было весело ходить за покупками», – сказал Кэн. Тут бабушка принесла мяч. «Мы только что поели, но давай немного поиграем», – сказала она. Они смеялись, перебрасывая мяч друг другу во дворе. Оказалось, бабушка тоже давно хотела поиграть в мяч."}}]}],"G":{"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いちばん":{"b":"一番 (いちばん)","p":"ad","m":{"az":"ən, birinci","en":"most, number one","ru":"самый, на первом месте"},"n":{"az":"Sifətlə üstünlük dərəcəsi yaradır: いちばん大きい - ən böyük.","en":"Forms a superlative with adjectives: いちばん大きい means the biggest.","ru":"Образует превосходную степень с прилагательными: いちばん大きい - самый большой."}},"いっしょ":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlikdə","en":"together","ru":"вместе"},"n":{"az":"いっしょに = birlikdə.","en":"いっしょに = together.","ru":"いっしょに = вместе."}},"いっぱい":{"b":"いっぱい","p":"ad","m":{"az":"çox, dolu","en":"a lot, full","ru":"много, полно"},"n":{"az":"いっぱい食べる “çox yemək”, おなかがいっぱい isə “tox olmaq” deməkdir.","en":"いっぱい食べる means “eat a lot,” while おなかがいっぱい means “be full.”","ru":"いっぱい食べる означает «много есть», а おなかがいっぱい означает «быть сытым»."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"うち":{"b":"うち (家)","p":"n","m":{"az":"ev, ailə","en":"home, household","ru":"дом, семья"},"n":{"az":"うちに帰る = evə qayıtmaq; うちの母 = mənim anam.","en":"うちに帰る = to return home; うちの母 = my mother.","ru":"うちに帰る = вернуться домой; うちの母 = моя мама."}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"おもしろい":{"b":"おもしろい","p":"ai","m":{"az":"maraqlı, əyləncəli","en":"interesting, amusing","ru":"интересный, забавный"},"n":{"az":"い-sifətdir və həm maraqlı, həm də gülməli mənasında işlənə bilər.","en":"An i-adjective that can mean either interesting or amusing.","ru":"Прилагательное на い, которое может означать интересный или забавный."}},"お客さん":{"b":"お客さん (おきゃくさん)","p":"n","m":{"az":"qonaq; müştəri","en":"guest; customer","ru":"гость; покупатель"},"n":{"az":"Evdə qonağı, mağaza və xidmət yerində müştərini bildirir.","en":"Means a guest at home or a customer in a shop or service setting.","ru":"Дома означает гостя, а в магазине или сфере услуг клиента."}},"お母さんたち":{"b":"お母さんたち (おかあさんたち)","p":"n","m":{"az":"analar","en":"mothers","ru":"матери"},"n":{"az":"たち insanları bildirən sözlərə qoşularaq cəm və ya qrup mənası yaradır.","en":"たち marks a plural or group of people.","ru":"たち обозначает множественное число или группу людей."}},"お金":{"b":"お金 (おかね)","p":"n","m":{"az":"pul","en":"money","ru":"деньги"}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かぶる":{"b":"被る (かぶる)","p":"v","m":{"az":"başa taxmaq; örtmək","en":"to wear on the head; to cover","ru":"надевать на голову; покрывать"},"n":{"az":"帽子をかぶる papaq taxmaq, かぶっています isə taxmış vəziyyətdə olmaq deməkdir.","en":"帽子をかぶる means to put on a hat, while かぶっています describes wearing it.","ru":"帽子をかぶる означает надеть шляпу, а かぶっています - быть в шляпе."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"きれい":{"b":"きれい","p":"an","m":{"az":"gözəl, təmiz","en":"beautiful, clean","ru":"красивый, чистый"},"n":{"az":"な-sifətdir: きれいな花 = gözəl çiçək; い ilə bitsə də い-sifət deyil.","en":"A na-adjective despite ending in い: きれいな花 = beautiful flower.","ru":"Это な-прилагательное, несмотря на окончание い: きれいな花 = красивый цветок."}},"くださる":{"b":"ください","p":"ex","m":{"az":"zəhmət olmasa (...edin)","en":"please (do ...)","ru":"пожалуйста (сделайте)"},"n":{"az":"Feilin te-formasından sonra nəzakətli xahiş: 見てください = baxın, zəhmət olmasa.","en":"After a te-form it makes a polite request: 見てください = please look.","ru":"После формы на -te – вежливая просьба: 見てください = посмотрите, пожалуйста."}},"くれる":{"b":"くれる","p":"v","m":{"az":"mənə vermək, bizim tərəfə vermək","en":"to give to me or my group","ru":"давать мне или кому-то из моей группы"},"n":{"az":"くれる verənin mənə və ya mənim tərəfimə nəsə verdiyini bildirir; 〜てくれる başqası üçün edilən yaxşılığı göstərir.","en":"くれる describes giving toward the speaker's side; 〜てくれる expresses a helpful action done for someone.","ru":"くれる обозначает передачу говорящему или его группе; 〜てくれる выражает действие, совершённое для чьей-то пользы."}},"けが":{"b":"怪我 (けが)","p":"n","m":{"az":"zədə, xəsarət","en":"injury","ru":"травма"},"n":{"az":"けがをする - zədələnmək.","en":"けがをする means to get injured.","ru":"けがをする означает получить травму."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"この":{"b":"この","p":"dm","m":{"az":"bu","en":"this","ru":"этот"},"n":{"az":"この大学 = bu universitet.","en":"この大学 = this university.","ru":"この大学 = этот университет."}},"これ":{"b":"これ","p":"pr","m":{"az":"bu; bu şey","en":"this; this thing","ru":"это; эта вещь"},"n":{"az":"Danışana yaxın şeyi bildirir və isimdən əvvəl işlənmir; isimdən əvvəl この gəlir.","en":"Refers to something near the speaker; use この before a noun.","ru":"Указывает на предмет рядом с говорящим; перед существительным используется この."}},"さとう":{"b":"砂糖 (さとう)","p":"n","m":{"az":"şəkər","en":"sugar","ru":"сахар"}},"し":{"b":"し","p":"pt","m":{"az":"həm də, üstəlik, çünki","en":"and, moreover, because","ru":"и, к тому же, ведь"},"n":{"az":"〜し、〜し bir neçə səbəb və ya xüsusiyyət sadalayır: 安いし、おいしいし.","en":"〜し lists multiple reasons or qualities: 安いし、おいしいし means cheap and tasty.","ru":"〜し перечисляет причины или качества: 安いし、おいしいし означает дешёвый и вкусный."}},"すぎる":{"b":"過ぎる (すぎる)","p":"v","m":{"az":"keçmək, həddi aşmaq","en":"to pass, to exceed","ru":"проходить, превышать"},"n":{"az":"Feildən və ya sifətdən sonra 〜すぎる həddindən artıq olmağı bildirir.","en":"After a verb or adjective stem, 〜すぎる means doing or being something too much.","ru":"После основы глагола или прилагательного 〜すぎる означает чрезмерность."}},"すばらしい":{"b":"素晴らしい (すばらしい)","p":"ai","m":{"az":"möhtəşəm, əla","en":"wonderful, excellent","ru":"замечательный, великолепный"},"n":{"az":"い-sifətdir, keçmiş forması すばらしかった olur.","en":"It is an i-adjective, with past form すばらしかった.","ru":"Это i-прилагательное, прошедшая форма すばらしかった."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"ずつ":{"b":"ずつ","p":"pt","m":{"az":"...-ar, hərəsi bir","en":"each, apiece","ru":"по (одному)"},"n":{"az":"一つずつ = hərəsi bir dənə.","en":"一つずつ = one each.","ru":"一つずつ = по одному."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"たたく":{"b":"叩く (たたく)","p":"v","m":{"az":"döymək; vurmaq","en":"to knock; to hit","ru":"стучать; ударять"},"n":{"az":"ドアをたたく qapını döymək deməkdir.","en":"ドアをたたく means to knock on a door.","ru":"ドアをたたく означает стучать в дверь."}},"たまご":{"b":"たまご","p":"n","m":{"az":"yumurta","en":"egg","ru":"яйцо"}},"だ":{"b":"だ (だ)","p":"cp","m":{"az":"-dır, -dir; olmaq","en":"to be; is, am, are","ru":"быть; являться"},"n":{"az":"なら şərt formasıdır: 学生なら, əgər tələbədirsə.","en":"なら is a conditional form: 学生なら means if someone is a student.","ru":"なら является условной формой: 学生なら означает если он студент."}},"つなぐ":{"b":"繋ぐ (つなぐ)","p":"v","m":{"az":"birləşdirmək, bağlamaq, əlaqələndirmək","en":"to connect, to tie, to link","ru":"соединять, связывать"},"n":{"az":"手をつなぐ əl-ələ tutmaq, 電話をつなぐ isə telefonla əlaqələndirmək deməkdir.","en":"手をつなぐ means to hold hands, while 電話をつなぐ means to connect a call.","ru":"手をつなぐ означает держаться за руки, а 電話をつなぐ - соединять по телефону."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とうとう":{"b":"とうとう (とうとう)","p":"ad","m":{"az":"nəhayət; axırda","en":"finally; at last; eventually","ru":"наконец; в конце концов"},"n":{"az":"Uzun müddətdən sonra baş verən, bəzən arzuolunmaz nəticəni bildirir.","en":"Indicates an eventual result after some time, sometimes an undesirable one.","ru":"Обозначает итог после долгого времени, иногда нежелательный."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"ところ":{"b":"所 (ところ)","p":"n","m":{"az":"yer; məqam; an","en":"place; point; moment","ru":"место; момент"},"n":{"az":"Vるところ başlanmaq üzrə olan, Vているところ davam edən, Vたところ isə yenicə bitmiş hərəkətdir.","en":"Vるところ means about to do, Vているところ means in progress, and Vたところ means just finished.","ru":"Vるところ означает собираюсь сделать, Vているところ процесс, а Vたところ только что закончил."}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"どう":{"b":"どう","p":"ad","m":{"az":"necə, nə cür","en":"how, in what way","ru":"как, каким образом"},"n":{"az":"どうですか = necədir, nə fikirləşirsiniz?","en":"どうですか asks how something is or what someone thinks.","ru":"どうですか означает «как это?» или «что вы думаете?»."}},"どこ":{"b":"どこ","p":"pr","m":{"az":"hara","en":"where","ru":"где, куда"},"n":{"az":"どこの国 = hansı ölkə.","en":"どこの国 = which country.","ru":"どこの国 = какая страна."}},"な":{"b":"な (な)","p":"pt","m":{"az":"qadağa hissəciyi; nida hissəciyi","en":"prohibitive particle; exclamatory particle","ru":"запретительная частица; восклицательная частица"},"n":{"az":"Feildən sonra 行くな qadağadır; いいな heyranlıq bildirir; な-sifətlərdə isə isimlə bağlayıcıdır.","en":"After a verb 行くな means do not go; いいな expresses admiration; な also links na-adjectives to nouns.","ru":"После глагола 行くな означает не ходи; いいな выражает восхищение; な также связывает прилагательные с существительными."}},"ないし":{"b":"ないし","p":"cj","m":{"az":"və ya, yaxud","en":"or, alternatively","ru":"или, либо"},"n":{"az":"Daha çox rəsmi dildə seçim və ya aralıq bildirir: 2ないし3人 - iki və ya üç nəfər.","en":"Mostly formal, indicating alternatives or a range: 2ないし3人 means two or three people.","ru":"Чаще используется официально для альтернативы или диапазона: 2ないし3人 - два или три человека."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"ねずみ":{"b":"ねずみ","p":"n","m":{"az":"siçan; siçovul","en":"mouse; rat","ru":"мышь; крыса"}},"ねずみたち":{"b":"ねずみ","p":"n","m":{"az":"siçanlar","en":"mice","ru":"мыши"},"n":{"az":"たち burada siçanların bir qrup olduğunu göstərir.","en":"たち marks a group of mice here.","ru":"たち здесь обозначает группу мышей."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"はっきり":{"b":"はっきり","p":"ad","m":{"az":"aydın şəkildə, dəqiq","en":"clearly, distinctly","ru":"ясно, отчётливо"},"n":{"az":"はっきり言う fikri açıq demək, はっきり見える isə aydın görünmək deməkdir.","en":"はっきり言う means to speak clearly, while はっきり見える means to be clearly visible.","ru":"はっきり言う означает говорить ясно, а はっきり見える - быть отчётливо видимым."}},"ばかり":{"b":"ばかり","p":"pt","m":{"az":"yalnız, ancaq, indicə","en":"only, just, nothing but","ru":"только, лишь, только что"},"n":{"az":"〜たばかり indicə baş vermiş hərəkəti, 名詞ばかり isə yalnız həmin şeyin çoxluğunu bildirir.","en":"〜たばかり means something happened recently, while noun + ばかり means nothing but that thing.","ru":"〜たばかり означает недавнее действие, а существительное + ばかり - только это и ничего другого."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まだ":{"b":"まだ","p":"ad","m":{"az":"hələ","en":"still, yet","ru":"ещё"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"もの":{"b":"物 (もの)","p":"n","m":{"az":"əşya, şey","en":"thing, object","ru":"вещь, предмет"},"n":{"az":"物 konkret əşyanı bildirir, もの isə bəzi ifadələrdə ümumi anlayış və ya səbəb də bildirə bilər.","en":"物 refers to things, while もの can also express general ideas or explanations in certain expressions.","ru":"物 обозначает предметы, а もの в некоторых выражениях также передаёт общие понятия или объяснения."}},"ゆっくり":{"b":"ゆっくり","p":"ad","m":{"az":"yavaş-yavaş, tələsmədən","en":"slowly","ru":"медленно"}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よい":{"b":"よい","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"い-sifətidir və いい ilə eynimənalıdır; よう bəzi ifadələrdə, məsələn おはよう-da görünən formadır.","en":"An い-adjective equivalent to いい; よう occurs in some expressions such as おはよう.","ru":"い-прилагательное, равнозначное いい; форма よう встречается в выражениях вроде おはよう."}},"りんご":{"b":"りんご","p":"n","m":{"az":"alma","en":"apple","ru":"яблоко"}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"アイドル":{"b":"アイドル","p":"n","m":{"az":"pop ulduzu, kumir","en":"pop idol, celebrity idol","ru":"поп-идол, кумир"},"n":{"az":"Yaponiyada çox vaxt müğənnilik və səhnə fəaliyyəti ilə məşğul olan pop ulduzlarına deyilir.","en":"In Japan, often refers to entertainers who sing and perform as idols.","ru":"В Японии часто обозначает артистов, выступающих как поп-идолы."}},"ケン":{"b":"ケン","p":"nm","m":{"az":"Ken (oğlan adı)","en":"Ken (boy's name)","ru":"Кен (мужское имя)"}},"ケーキ":{"b":"ケーキ","p":"n","m":{"az":"tort, pirojna","en":"cake","ru":"торт, пирожное"}},"コンサート":{"b":"コンサート","p":"n","m":{"az":"konsert","en":"concert","ru":"концерт"}},"ステージ":{"b":"ステージ","p":"n","m":{"az":"səhnə","en":"stage","ru":"сцена"}},"ダンス":{"b":"ダンス","p":"n","m":{"az":"rəqs","en":"dance; dancing","ru":"танец; танцы"},"n":{"az":"ダンスをする = rəqs etmək.","en":"ダンスをする means to dance.","ru":"ダンスをする означает танцевать."}},"チョコレート":{"b":"チョコレート","p":"n","m":{"az":"şokolad","en":"chocolate","ru":"шоколад"}},"トマト":{"b":"トマト","p":"n","m":{"az":"pomidor","en":"tomato","ru":"помидор"}},"ハナ":{"b":"ハナ","p":"nm","m":{"az":"Hana (qız adı)","en":"Hana (girl's name)","ru":"Хана (женское имя)"}},"パン":{"b":"パン","p":"n","m":{"az":"çörək","en":"bread","ru":"хлеб"}},"プー":{"b":"プー","p":"n","m":{"az":"Pu, personaj adı","en":"Poo, character name","ru":"Пу, имя персонажа"},"n":{"az":"Xüsusi ad kimi işlənərsə, adətən tərcümə olunmur.","en":"When used as a character name, it is normally transliterated.","ru":"Когда используется как имя персонажа, обычно передаётся транслитерацией."}},"ボール":{"b":"ボール (ぼーる)","p":"n","m":{"az":"top","en":"ball","ru":"мяч"}},"ミオ":{"b":"ミオ (ミオ)","p":"nm","m":{"az":"Mio; şəxs adı","en":"Mio; personal name","ru":"Мио; личное имя"}},"メモ":{"b":"メモ (めも)","p":"n","m":{"az":"qeyd, qısa yazı","en":"note, memo","ru":"заметка, записка"}},"ユキ":{"b":"ユキ","p":"nm","m":{"az":"Yuki (qız adı, 'qar' deməkdir)","en":"Yuki (girl's name, means 'snow')","ru":"Юки (имя, значит 'снег')"}},"一度":{"b":"一度 (いちど)","p":"n","m":{"az":"bir dəfə","en":"once","ru":"один раз"}},"三人":{"b":"三人 (さんにん)","p":"nu","m":{"az":"üç nəfər","en":"three people","ru":"три человека"},"n":{"az":"人 insan sayğacıdır: 一人 hitori, 二人 futari, 三人 sannin.","en":"人 counts people: 一人 hitori, 二人 futari, 三人 sannin.","ru":"人 считает людей: 一人 hitori, 二人 futari, 三人 sannin."}},"三日":{"b":"三日 (みっか)","p":"nu","m":{"az":"ayın üçüncü günü, üç gün","en":"third day of the month, three days","ru":"третье число месяца, три дня"},"n":{"az":"Tarix və müddət bildirir, 三日 みっか oxunur.","en":"Used for a date or duration, pronounced みっか.","ru":"Обозначает дату или длительность, читается みっか."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"上手":{"b":"上手 (じょうず)","p":"an","m":{"az":"bacarıqlı, yaxşı bacaran","en":"skillful, good at","ru":"умелый, хорошо умеющий"},"n":{"az":"な-sifətdir: ピアノが上手です = pianoda yaxşı çalır.","en":"A na-adjective: ピアノが上手です = is good at playing piano.","ru":"な-прилагательное: ピアノが上手です = хорошо играет на пианино."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"不思議":{"b":"不思議 (ふしぎ)","p":"an","m":{"az":"sirli; qəribə","en":"mysterious; curious","ru":"загадочный; удивительный"},"n":{"az":"な-sifətidir: 不思議な話; isim kimi «sirr, möcüzə» də bildirir.","en":"A な-adjective: 不思議な話; as a noun it can mean a mystery or wonder.","ru":"な-прилагательное: 不思議な話; как существительное может означать тайну или чудо."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"丸い":{"b":"丸い (まるい)","p":"ai","m":{"az":"yumru, dairəvi","en":"round","ru":"круглый"},"n":{"az":"月が丸くなる = Ay bədirlənir.","en":"月が丸くなる = the moon becomes full.","ru":"月が丸くなる = луна становится полной."}},"二つ目":{"b":"二つ目 (ふたつめ)","p":"n","m":{"az":"ikinci, ikinci şey","en":"the second one, second item","ru":"второй, второй предмет"},"n":{"az":"二つ目 əşyaları və ya variantları sıralayarkən işlənir.","en":"Used when identifying the second item or option.","ru":"Используется для обозначения второго предмета или варианта."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"人たち":{"b":"人たち (ひとたち)","p":"n","m":{"az":"adamlar, camaat","en":"people","ru":"люди"}},"人気者":{"b":"人気者 (にんきもの)","p":"n","m":{"az":"hamının sevimlisi; məşhur adam","en":"popular person; everyone's favorite","ru":"любимец публики; популярный человек"}},"今度":{"b":"今度 (こんど)","p":"n","m":{"az":"bu dəfə, gələn dəfə","en":"this time, next time","ru":"на этот раз, в следующий раз"},"n":{"az":"Kontekstdən asılı olaraq indiki və ya növbəti hadisəni bildirir.","en":"Depending on context, it refers to the present occasion or the next one.","ru":"В зависимости от контекста обозначает нынешний или следующий случай."}},"今日":{"b":"今日 (きょう)","p":"n","m":{"az":"bu gün","en":"today","ru":"сегодня"}},"休む":{"b":"休む (やすむ)","p":"v","m":{"az":"istirahət etmək, işə və ya dərsə getməmək","en":"rest, take time off","ru":"отдыхать, пропускать работу или занятия"},"n":{"az":"学校を休む “dərsə getməmək”, 会社を休む isə “işə getməmək” deməkdir.","en":"学校を休む means “miss school,” and 会社を休む means “take time off work.”","ru":"学校を休む означает «пропускать занятия», а 会社を休む означает «не идти на работу»."}},"会":{"b":"会 (かい)","p":"n","m":{"az":"toplantı, yığıncaq, tədbir","en":"meeting, gathering, event","ru":"собрание, встреча, мероприятие"}},"会場":{"b":"会場 (かいじょう)","p":"n","m":{"az":"tədbir məkanı, tədbirin keçirildiyi yer","en":"venue, event location","ru":"место проведения мероприятия"}},"住む":{"b":"住む (すむ)","p":"v","m":{"az":"yaşamaq, məskunlaşmaq","en":"to live, to reside","ru":"жить, проживать"},"n":{"az":"住んで て-formadır, 場所に住む müəyyən yerdə yaşamaq deməkdir.","en":"住んで is the te-form, and 場所に住む means to live in a place.","ru":"住んで - форма на て, 場所に住む означает жить в определённом месте."}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"元気":{"b":"元気 (げんき)","p":"an","m":{"az":"gümrah; sağlam","en":"energetic; well","ru":"бодрый; здоровый"},"n":{"az":"な-sifətidir: 元気な子; 元気です = özünü yaxşı hiss edir.","en":"A な-adjective: 元気な子; 元気です means being well.","ru":"な-прилагательное: 元気な子; 元気です означает хорошее самочувствие."}},"先生":{"b":"先生 (せんせい)","p":"n","m":{"az":"müəllim; həkim","en":"teacher; doctor","ru":"учитель; доктор"},"n":{"az":"Başqasına müraciət kimi işlənir (ミミ先生 = Mimi həkim). Özün haqqında 先生 demirsən, 教師 deyirsən.","en":"Used to address others (ミミ先生 = Doctor Mimi). Never about yourself – then you say 教師.","ru":"Используется как обращение (ミミ先生 = доктор Мими). О себе так не говорят – говорят 教師."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"冠":{"b":"冠 (かんむり)","p":"n","m":{"az":"tac","en":"crown","ru":"корона"}},"出かける":{"b":"出かける (でかける)","p":"v","m":{"az":"evdən çıxmaq; yola düşmək","en":"go out; set off","ru":"выходить; отправляться"}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"初めて":{"b":"初めて (はじめて)","p":"ad","m":{"az":"ilk dəfə","en":"for the first time","ru":"впервые"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"割る":{"b":"割る (わる)","p":"v","m":{"az":"sındırmaq, bölmək","en":"to break, to split","ru":"разбивать, разделять"},"n":{"az":"割る təsirli feldir, 割れる isə bir şeyin sınmasını və ya çatlamasını bildirir.","en":"割る is transitive, while 割れる is intransitive.","ru":"割る переходный глагол, а 割れる непереходный."}},"動かし方":{"b":"動かし方 (うごかしかた)","p":"n","m":{"az":"hərəkət etdirmə üsulu, idarəetmə qaydası","en":"way to move, how to operate","ru":"способ движения, способ управления"},"n":{"az":"Felin ます kökü + 方 hərəkətin necə edildiyini bildirir.","en":"The masu-stem + 方 expresses how to perform an action.","ru":"Основа формы ます + 方 обозначает способ выполнения действия."}},"動き":{"b":"動き (うごき)","p":"n","m":{"az":"hərəkət, hərəkətlilik","en":"movement, motion","ru":"движение"}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"向こう":{"b":"向こう (むこう)","p":"n","m":{"az":"o tərəf, qarşı tərəf","en":"over there, the other side","ru":"там, противоположная сторона"}},"吹き方":{"b":"吹き方 (ふきかた)","p":"n","m":{"az":"üfürmə üsulu, çalma qaydası","en":"way of blowing, how to play a wind instrument","ru":"способ дуть, способ игры на духовом инструменте"},"n":{"az":"吹く felinin kökünə 方 artırılaraq üsul bildirilir.","en":"方 attaches to the masu-stem of 吹く to describe how to blow or play.","ru":"方 присоединяется к основе 吹く и обозначает способ действия."}},"吹く":{"b":"吹く (ふく)","p":"v","m":{"az":"əsmək; üfürmək; çalmaq","en":"to blow; to play a wind instrument","ru":"дуть; веять; играть на духовом инструменте"},"n":{"az":"風が吹く külək əsmək, 笛を吹く fleyta çalmaqdır.","en":"風が吹く means the wind blows; 笛を吹く means to play a flute.","ru":"風が吹く означает ветер дует; 笛を吹く означает играть на флейте."}},"品物":{"b":"品物 (しなもの)","p":"n","m":{"az":"mal, əşya, məhsul","en":"goods, item, merchandise","ru":"товар, вещь"}},"喜ぶ":{"b":"喜ぶ (よろこぶ)","p":"v","m":{"az":"sevinmək, şadlanmaq","en":"to rejoice, to be pleased","ru":"радоваться, обрадоваться"},"n":{"az":"I qrup feldir: 喜びました = sevindi; プレゼントを喜ぶ = hədiyyəyə sevinmək.","en":"A Group 1 verb: 喜びました = was pleased; プレゼントを喜ぶ = to be delighted with a gift.","ru":"Глагол I группы: 喜びました = обрадовался; プレゼントを喜ぶ = радоваться подарку."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"変":{"b":"変 (へん)","p":"an","m":{"az":"qəribə","en":"strange; odd","ru":"странный"},"n":{"az":"な-sifətidir: 変な音 = qəribə səs.","en":"A な-adjective: 変な音 = a strange sound.","ru":"な-прилагательное: 変な音 = странный звук."}},"夕方":{"b":"夕方 (ゆうがた)","p":"n","m":{"az":"axşamüstü","en":"evening","ru":"вечер"}},"外":{"b":"外 (そと)","p":"n","m":{"az":"çöl, bayır","en":"outside","ru":"снаружи"},"n":{"az":"N の 外 = N-in çölü: 窓の外 = pəncərənin arxası (çöldə).","en":"N の 外 = outside N.","ru":"N の 外 = снаружи N."}},"多い":{"b":"多い (おおい)","p":"ai","m":{"az":"çox; çoxsaylı","en":"many; numerous","ru":"многочисленный; много"},"n":{"az":"い-sifətdir; 多くて bağlayıcı formadır və adətən 人が多い deyilir.","en":"It is an i-adjective; 多くて is its linking form, and 人が多い is the usual pattern.","ru":"Это i-прилагательное; 多くて - соединительная форма, обычно говорят 人が多い."}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"夢中":{"b":"夢中 (むちゅう)","p":"an","m":{"az":"başını qatmış, aludə olmuş","en":"absorbed, engrossed","ru":"увлечённый, поглощённый"},"n":{"az":"な-sifətdir: 夢中になる bir şeyə aludə olmaq, 夢中で etmək isə həvəslə məşğul olmaq deməkdir.","en":"It is a na-adjective: 夢中になる means to become absorbed, and 夢中で means while engrossed.","ru":"Это na-прилагательное: 夢中になる означает увлечься, а 夢中で - быть полностью поглощённым действием."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"好き":{"b":"好き (すき)","p":"an","m":{"az":"sevimli; sevmək","en":"liked; to like","ru":"любимый; нравиться"},"n":{"az":"N が好きです = N-i sevirəm. Yaponcada 'sevmək' sifətlə deyilir.","en":"N が好きです = I like N. 'To like' is an adjective in Japanese.","ru":"N が好きです = мне нравится N. 'Нравиться' – прилагательное."}},"始まる":{"b":"始まる (はじまる)","p":"v","m":{"az":"başlamaq","en":"to begin; to start","ru":"начинаться"},"n":{"az":"Təsirsizdir: 祭りが始まります; təsirli qarşılığı 始める-dir.","en":"Intransitive: 祭りが始まります; its transitive partner is 始める.","ru":"Непереходный: 祭りが始まります; переходная пара: 始める."}},"始める":{"b":"始める (はじめる)","p":"v","m":{"az":"başlamaq, başlatmaq","en":"to begin, to start something","ru":"начинать"},"n":{"az":"Təsirli feldir, 勉強を始めます dərsə başlamaqdır, təsirsiz qarşılığı 始まる-dur.","en":"Transitive: 勉強を始めます means start studying, while 始まる is intransitive.","ru":"Переходный глагол: 勉強を始めます - начать учёбу, непереходный вариант 始まる."}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"子ども":{"b":"子ども (こども)","p":"n","m":{"az":"uşaq","en":"child","ru":"ребёнок"}},"子どもたち":{"b":"子どもたち (こどもたち)","p":"n","m":{"az":"uşaqlar","en":"children","ru":"дети"},"n":{"az":"たち insanları və bəzən canlıları bildirən sözlərə cəm və ya qrup mənası verir.","en":"たち marks a plural or group, mainly with words for people and sometimes other living beings.","ru":"たち обозначает множественность или группу, главным образом у слов, называющих людей, иногда других живых существ."}},"字":{"b":"字 (じ)","p":"n","m":{"az":"hərf, yazı","en":"character, handwriting","ru":"письменный знак, почерк"}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"守る":{"b":"守る (まもる)","p":"v","m":{"az":"qorumaq; qaydaya əməl etmək","en":"to protect; to obey","ru":"защищать; соблюдать"},"n":{"az":"約束を守る sözünə əməl etməkdir; 守らなければ zərurət bildirən quruluşda işlənir.","en":"約束を守る means to keep a promise; 守らなければ is used in obligation patterns.","ru":"約束を守る означает сдержать обещание; 守らなければ используется в конструкциях обязанности."}},"安心":{"b":"安心 (あんしん)","p":"n","m":{"az":"rahatlıq; arxayınlıq","en":"relief; peace of mind","ru":"облегчение; спокойствие"},"n":{"az":"安心する rahatlanmaq və ya arxayın olmaq deməkdir.","en":"安心する means to feel relieved or at ease.","ru":"安心する означает почувствовать облегчение или успокоиться."}},"実":{"b":"実 (み)","p":"n","m":{"az":"meyvə, bar, toxum","en":"fruit, berry, seed","ru":"плод, ягода, семя"},"n":{"az":"実がなる - ağacın və ya bitkinin bar verməsi.","en":"実がなる means for a tree or plant to bear fruit.","ru":"実がなる означает плодоносить."}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"小さい":{"b":"小さい (ちいさい)","p":"ai","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"i-sifət; isimdən əvvəl olduğu kimi gəlir: 小さい子 = balaca uşaq.","en":"i-adjective; goes straight before a noun: 小さい子 = a little child.","ru":"i-прилагательное; ставится прямо перед существительным."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"川":{"b":"川 (かわ)","p":"n","m":{"az":"çay","en":"river","ru":"река"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"帽子":{"b":"帽子 (ぼうし)","p":"n","m":{"az":"papaq; şlyapa","en":"hat; cap","ru":"шляпа; шапка"}},"店":{"b":"店 (みせ)","p":"n","m":{"az":"mağaza; dükan","en":"shop; store","ru":"магазин; лавка"}},"庭":{"b":"庭 (にわ)","p":"n","m":{"az":"bağça, həyət","en":"garden, yard","ru":"сад, двор"}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"後ろ":{"b":"後ろ (うしろ)","p":"n","m":{"az":"arxa, arxa tərəf","en":"back, behind","ru":"задняя сторона, позади"},"n":{"az":"Nの後ろ bir şeyin arxasını bildirir: 家の後ろ evin arxası.","en":"Nの後ろ means behind something: 家の後ろ, behind the house.","ru":"Nの後ろ означает «позади чего-либо»: 家の後ろ, за домом."}},"心配":{"b":"心配 (しんぱい)","p":"n","m":{"az":"narahatlıq, qayğı","en":"worry, concern","ru":"беспокойство, тревога"},"n":{"az":"心配する “narahat olmaq” deməkdir; 心配な şəklində na-sifəti kimi də işlənir.","en":"心配する means “worry”; 心配な is also used as a na-adjective.","ru":"心配する означает «беспокоиться»; форма 心配な также употребляется как прилагательное на な."}},"忘れる":{"b":"忘れる (わすれる)","p":"v","m":{"az":"unutmaq","en":"to forget","ru":"забывать"},"n":{"az":"Nを忘れる həm nəyisə unutmaq, həm də bir yerdə qoyub gəlmək mənasında işlənir.","en":"Nを忘れる can mean to forget something or leave it behind.","ru":"Nを忘れる может означать забыть что-либо или оставить это где-либо."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"急":{"b":"急 (きゅう)","p":"an","m":{"az":"qəfil, birdən","en":"sudden","ru":"внезапный"},"n":{"az":"急に = birdən, qəfildən.","en":"急に = suddenly.","ru":"急に = вдруг."}},"急ぐ":{"b":"急ぐ (いそぐ)","p":"v","m":{"az":"tələsmək","en":"hurry","ru":"спешить"},"n":{"az":"て forması 急いで olur.","en":"Its て-form is 急いで.","ru":"Форма на て: 急いで."}},"悪い":{"b":"悪い (わるい)","p":"ai","m":{"az":"pis, yaramaz","en":"bad, wrong","ru":"плохой, неправильный"},"n":{"az":"い-sifətdir: 悪くない = pis deyil; 調子が悪い = halı pis olmaq.","en":"An i-adjective: 悪くない = not bad; 調子が悪い = to feel unwell.","ru":"Прилагательное на い: 悪くない = неплохой; 調子が悪い = плохо себя чувствовать."}},"手":{"b":"手 (て)","p":"n","m":{"az":"əl","en":"hand","ru":"рука"}},"手伝い":{"b":"手伝い (てつだい)","p":"n","m":{"az":"kömək, yardım","en":"help, assistance","ru":"помощь"}},"払う":{"b":"払う (はらう)","p":"v","m":{"az":"ödəmək, pul vermək","en":"to pay","ru":"платить, оплачивать"},"n":{"az":"お金を払う - pul ödəmək; 払いました nəzakətli keçmiş zamandır.","en":"お金を払う means to pay money; 払いました is polite past tense.","ru":"お金を払う означает платить деньги; 払いました - вежливое прошедшее время."}},"投げる":{"b":"投げる (なげる)","p":"v","m":{"az":"atmaq, tullamaq","en":"to throw, to toss","ru":"бросать, кидать"},"n":{"az":"投げながら eyni vaxtda başqa hərəkət edərkən atmaq mənasını verir.","en":"投げながら means throwing while doing another action.","ru":"投げながら означает бросать одновременно с другим действием."}},"拍手":{"b":"拍手 (はくしゅ)","p":"n","m":{"az":"alqış","en":"applause, clapping","ru":"аплодисменты"},"n":{"az":"拍手する - alqışlamaq.","en":"拍手する means to clap or applaud.","ru":"拍手する означает аплодировать."}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"探す":{"b":"探す (さがす)","p":"v","m":{"az":"axtarmaq","en":"to search for, to look for","ru":"искать"},"n":{"az":"探しましょう birlikdə axtarmağı təklif edir.","en":"探しましょう means \"Let's look for it.\"","ru":"探しましょう означает «Давайте поищем»."}},"教える":{"b":"教える (おしえる)","p":"v","m":{"az":"öyrətmək; demək (məlumat vermək)","en":"to teach; to tell","ru":"учить; сообщать"},"n":{"az":"名前を教えてください = adınızı deyin (zəhmət olmasa).","en":"名前を教えてください = please tell me your name.","ru":"名前を教えてください = скажите, пожалуйста, имя."}},"料理":{"b":"料理 (りょうり)","p":"n","m":{"az":"yemək, yemək bişirmə","en":"dish, cooking","ru":"блюдо, приготовление пищи"},"n":{"az":"料理 yeməyi və yemək bişirməni, 料理する isə bişirmək hərəkətini bildirir.","en":"料理 means a dish or cooking; 料理する means to cook.","ru":"料理 означает блюдо или приготовление пищи; 料理する значит готовить."}},"新しい":{"b":"新しい (あたらしい)","p":"ai","m":{"az":"yeni","en":"new","ru":"новый"}},"方法":{"b":"方法 (ほうほう)","p":"n","m":{"az":"üsul, metod, yol","en":"method, way","ru":"метод, способ"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"明るい":{"b":"明るい (あかるい)","p":"ai","m":{"az":"işıqlı, parlaq","en":"bright","ru":"светлый, яркий"},"n":{"az":"明るく光る = parlaq işıq saçmaq.","en":"明るく光る = shine brightly.","ru":"明るく光る = ярко светиться."}},"星":{"b":"星 (ほし)","p":"n","m":{"az":"ulduz","en":"star","ru":"звезда"}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"最初":{"b":"最初 (さいしょ)","p":"n","m":{"az":"başlanğıc, əvvəl, birinci","en":"beginning, first","ru":"начало, сначала, первый"},"n":{"az":"最初に - əvvəlcə, ilk olaraq.","en":"最初に means first or at the beginning.","ru":"最初に означает сначала или в первую очередь."}},"最後":{"b":"最後 (さいご)","p":"n","m":{"az":"son, axır","en":"end, last","ru":"конец, последний"}},"服":{"b":"服 (ふく)","p":"n","m":{"az":"paltar","en":"clothes","ru":"одежда"}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"本当":{"b":"本当 (ほんとう)","p":"n","m":{"az":"həqiqət, doğru","en":"truth, reality","ru":"правда, истина"},"n":{"az":"本当です doğru deməkdir, 本当に isə həqiqətən mənasını verir.","en":"本当です means it is true, while 本当に means really.","ru":"本当です означает это правда, а 本当に - действительно."}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"楽しい":{"b":"楽しい (たのしい)","p":"ai","m":{"az":"əyləncəli; xoş","en":"fun; enjoyable","ru":"весёлый; приятный"},"n":{"az":"İ-sifətdir; 楽しく onun zərf formasıdır.","en":"An i-adjective; 楽しく is its adverbial form.","ru":"И-прилагательное; 楽しく является его наречной формой."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"歌":{"b":"歌 (うた)","p":"n","m":{"az":"mahnı","en":"song","ru":"песня"}},"歌い出す":{"b":"歌い出す (うたいだす)","p":"v","m":{"az":"oxumağa başlamaq","en":"to start singing","ru":"начать петь"},"n":{"az":"Felin ます kökü + 出す hərəkətin başlamasını, çox vaxt qəfil başlanmasını bildirir.","en":"The masu-stem + 出す indicates the start of an action, often suddenly.","ru":"Основа формы ます + 出す обозначает начало действия, часто внезапное."}},"歌う":{"b":"歌う (うたう)","p":"v","m":{"az":"oxumaq; mahnı oxumaq","en":"to sing","ru":"петь"},"n":{"az":"歌を歌う = mahnı oxumaq; て-forması 歌って-dir.","en":"歌を歌う means to sing a song; its て-form is 歌って.","ru":"歌を歌う означает петь песню; て-форма: 歌って."}},"止まる":{"b":"止まる (とまる)","p":"v","m":{"az":"dayanmaq","en":"to stop","ru":"останавливаться"},"n":{"az":"Təsirsizdir: バスが止まる; təsirli qarşılığı 止める-dir.","en":"Intransitive: バスが止まる; its transitive partner is 止める.","ru":"Непереходный: バスが止まる; переходная пара: 止める."}},"歩く":{"b":"歩く (あるく)","p":"v","m":{"az":"yerimək; piyada getmək","en":"walk","ru":"ходить; идти пешком"},"n":{"az":"歩いて piyada deməkdir; keçilən yol を ilə göstərilə bilər: 道を歩く.","en":"歩いて means on foot; the route can take を: 道を歩く.","ru":"歩いて означает пешком; путь может оформляться を: 道を歩く."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"気づく":{"b":"気づく (きづく)","p":"v","m":{"az":"fərqinə varmaq, hiss etmək","en":"to notice, to realize","ru":"замечать, осознавать"},"n":{"az":"気づく adətən に ilə işlənir: 間違いに気づく - səhvi fərq etmək.","en":"気づく commonly takes に: 間違いに気づく means to notice a mistake.","ru":"気づく обычно употребляется с に: 間違いに気づく - заметить ошибку."}},"気持ち":{"b":"気持ち (きもち)","p":"n","m":{"az":"hiss, əhval, duyğu","en":"feeling, mood","ru":"чувство, настроение"},"n":{"az":"気持ちがいい xoş hiss etmək, 気持ちが悪い isə özünü pis hiss etmək deməkdir.","en":"気持ちがいい means feeling good, while 気持ちが悪い means feeling unpleasant or sick.","ru":"気持ちがいい означает приятное ощущение, а 気持ちが悪い означает неприятное самочувствие."}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"決まる":{"b":"決まる (きまる)","p":"v","m":{"az":"qərarlaşdırılmaq, müəyyənləşmək","en":"to be decided, to be settled","ru":"решаться, определяться"},"n":{"az":"決まる təsirsiz, 決める isə qərar vermək mənasında təsirli feldir.","en":"決まる is intransitive, while 決める means to decide something.","ru":"決まる непереходный глагол, а 決める означает решать что-либо."}},"泣く":{"b":"泣く (なく)","p":"v","m":{"az":"ağlamaq","en":"to cry","ru":"плакать"}},"海":{"b":"海 (うみ)","p":"n","m":{"az":"dəniz","en":"sea","ru":"море"}},"渡す":{"b":"渡す (わたす)","p":"v","m":{"az":"vermək, uzatmaq","en":"hand over, pass","ru":"передавать"},"n":{"az":"Keçişli feldir: 人に物を渡す “kiməsə nəsə vermək”; 渡る isə “qarşı tərəfə keçmək” deməkdir.","en":"A transitive verb: 人に物を渡す means “hand something to someone”; 渡る means “cross.”","ru":"Переходный глагол: 人に物を渡す «передать кому-то что-то»; 渡る означает «пересекать, переходить»."}},"滑る":{"b":"滑る (すべる)","p":"v","m":{"az":"sürüşmək, sürüşüb getmək","en":"to slip, to slide","ru":"скользить, поскальзываться"},"n":{"az":"滑りやすい felin kökü + やすい quruluşudur və asanlıqla sürüşən deməkdir.","en":"滑りやすい uses the masu-stem + やすい and means slippery or easy to slip on.","ru":"滑りやすい образовано от основы формы ます + やすい и означает скользкий."}},"焼ける":{"b":"焼ける (やける)","p":"v","m":{"az":"bişmək, yanmaq, qızarmaq","en":"to be cooked, to burn, to be baked","ru":"печься, подгорать, обгорать"},"n":{"az":"焼ける təsirsiz feldir, 焼く isə bir şeyi bişirmək və ya yandırmaq deməkdir.","en":"焼ける is intransitive, while 焼く means to cook, bake, or burn something.","ru":"焼ける непереходный глагол, а 焼く означает жарить, печь или сжигать что-либо."}},"特別":{"b":"特別 (とくべつ)","p":"an","m":{"az":"xüsusi; özəl","en":"special; particular","ru":"особенный; специальный"},"n":{"az":"Na-sifətdir: 特別な日 xüsusi gün deməkdir.","en":"A na-adjective: 特別な日 means a special day.","ru":"На-прилагательное: 特別な日 означает особенный день."}},"甘い":{"b":"甘い (あまい)","p":"ai","m":{"az":"şirin, yumşaq","en":"sweet, lenient","ru":"сладкий, снисходительный"},"n":{"az":"い-sifətdir: 甘くない = şirin deyil; davranış haqqında yumşaqlıq da bildirir.","en":"An i-adjective: 甘くない = not sweet; it can also mean lenient.","ru":"Прилагательное на い: 甘くない = несладкий; также может означать снисходительный."}},"男":{"b":"男 (おとこ)","p":"n","m":{"az":"kişi","en":"man, male","ru":"мужчина"},"n":{"az":"Nəzakətli gündəlik nitqdə kişi üçün çox vaxt 男の人 işlənir.","en":"男の人 is often used for a man in polite everyday speech.","ru":"В вежливой повседневной речи о мужчине часто говорят 男の人."}},"男の子":{"b":"男の子 (おとこのこ)","p":"n","m":{"az":"oğlan","en":"boy","ru":"мальчик"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"町長":{"b":"町長 (ちょうちょう)","p":"n","m":{"az":"qəsəbə başçısı","en":"town mayor","ru":"глава посёлка"}},"疲れる":{"b":"疲れる (つかれる)","p":"v","m":{"az":"yorulmaq","en":"to get tired","ru":"уставать"},"n":{"az":"疲れました - yoruldum; 疲れています - yorğunam.","en":"疲れました means got tired; 疲れています means am tired.","ru":"疲れました означает устал; 疲れています - я устал и сейчас чувствую усталость."}},"痛い":{"b":"痛い (いたい)","p":"ai","m":{"az":"ağrılı; ağrıyan","en":"painful; hurting","ru":"болезненный; болит"},"n":{"az":"い-sifətdir; keçmiş forması 痛かった deməkdir.","en":"An i-adjective; 痛かった is its past form.","ru":"Прилагательное на い; 痛かった является формой прошедшего времени."}},"着く":{"b":"着く (つく)","p":"v","m":{"az":"çatmaq; yetişmək","en":"to arrive; to reach","ru":"прибывать; добираться"},"n":{"az":"Yerə çatmağı bildirir və adətən に ilə işlənir: 駅に着く.","en":"Indicates arrival at a place and usually takes に: 駅に着く.","ru":"Обозначает прибытие в место и обычно употребляется с に: 駅に着く."}},"着る":{"b":"着る (きる)","p":"v","m":{"az":"geyinmək (paltar)","en":"to wear, put on","ru":"надевать"},"n":{"az":"白い服を着たねこ = ağ paltar geyinmiş pişik (feil təyin kimi).","en":"白い服を着たねこ = a cat wearing white.","ru":"白い服を着たねこ = кошка в белом."}},"短い":{"b":"短い (みじかい)","p":"ai","m":{"az":"qısa","en":"short","ru":"короткий"},"n":{"az":"い-sifətdir; 短かった keçmiş zamandır.","en":"An i-adjective; 短かった is the past form.","ru":"Прилагательное на い; 短かった является прошедшей формой."}},"私たち":{"b":"私たち (わたしたち)","p":"pr","m":{"az":"biz","en":"we, us","ru":"мы, нас"},"n":{"az":"たち şəxs əvəzliyini cəm formasına çevirir.","en":"たち makes a personal pronoun plural.","ru":"たち образует множественное число личного местоимения."}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"笑顔":{"b":"笑顔 (えがお)","p":"n","m":{"az":"təbəssüm, gülər üz","en":"smile, smiling face","ru":"улыбка, улыбающееся лицо"}},"笛":{"b":"笛 (ふえ)","p":"n","m":{"az":"fit, fleyta, nəfəs aləti","en":"whistle, flute","ru":"свисток, флейта"}},"笛吹き":{"b":"笛吹き (ふえふき)","p":"n","m":{"az":"fleytaçı, tütəkçi","en":"flute player, piper","ru":"флейтист, дудочник"}},"簡単":{"b":"簡単 (かんたん)","p":"an","m":{"az":"asan; sadə","en":"easy; simple","ru":"лёгкий; простой"},"n":{"az":"な-sifətdir; isimdən əvvəl 簡単な işlənir.","en":"A na-adjective; use 簡単な before a noun.","ru":"Прилагательное на な; перед существительным используется 簡単な."}},"約束":{"b":"約束 (やくそく)","p":"n","m":{"az":"söz; görüş razılaşması","en":"promise; appointment","ru":"обещание; договорённость о встрече"},"n":{"az":"約束する = söz vermək və ya görüş barədə razılaşmaq.","en":"約束する means to promise or arrange to meet.","ru":"約束する означает обещать или договариваться о встрече."}},"紙":{"b":"紙 (かみ)","p":"n","m":{"az":"kağız","en":"paper","ru":"бумага"}},"終わる":{"b":"終わる (おわる)","p":"v","m":{"az":"bitmək; sona çatmaq","en":"to end; to finish","ru":"заканчиваться"},"n":{"az":"Adətən təsirsizdir: 試験が終わります; təsirli qarşılığı 終える-dir.","en":"Usually intransitive: 試験が終わります; its transitive partner is 終える.","ru":"Обычно непереходный: 試験が終わります; переходная пара: 終える."}},"続ける":{"b":"続ける (つづける)","p":"v","m":{"az":"davam etdirmək","en":"to continue, to keep doing","ru":"продолжать"},"n":{"az":"続ける təsirli feildir, 続く isə bir şeyin davam etməsini bildirir.","en":"続ける is transitive, while 続く means something continues.","ru":"続ける переходный глагол, а 続く означает продолжаться."}},"緊張":{"b":"緊張 (きんちょう)","p":"n","m":{"az":"həyəcan, gərginlik","en":"nervousness, tension","ru":"волнение, напряжение"},"n":{"az":"緊張する həyəcanlanmaq və ya gərgin olmaq deməkdir.","en":"緊張する means to become nervous or tense.","ru":"緊張する означает волноваться или напрягаться."}},"練習":{"b":"練習 (れんしゅう)","p":"n","m":{"az":"məşq, praktika","en":"practice, training","ru":"практика, тренировка"},"n":{"az":"練習する = məşq etmək; ピアノの練習 = piano məşqi.","en":"練習する = to practice; ピアノの練習 = piano practice.","ru":"練習する = тренироваться; ピアノの練習 = занятие на пианино."}},"練習室":{"b":"練習室 (れんしゅうしつ)","p":"n","m":{"az":"məşq otağı","en":"practice room, rehearsal room","ru":"комната для занятий, репетиционная"}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"花":{"b":"花 (はな)","p":"n","m":{"az":"çiçək","en":"flower","ru":"цветок"}},"花畑":{"b":"花畑 (はなばたけ)","p":"n","m":{"az":"çiçək tarlası, çiçəklik","en":"flower field, flower garden","ru":"цветочное поле, цветник"}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見える":{"b":"見える (みえる)","p":"v","m":{"az":"görünmək","en":"to be visible, to appear","ru":"быть видным"},"n":{"az":"道が見えました = yol göründü (が ilə).","en":"道が見えました = a path came into view.","ru":"道が見えました = показалась дорога."}},"見せる":{"b":"見せる (みせる)","p":"v","m":{"az":"göstərmək","en":"show","ru":"показывать"},"n":{"az":"人に物を見せる kiməsə nəyisə göstərmək quruluşudur.","en":"Use 人に物を見せる to show something to someone.","ru":"Конструкция 人に物を見せる означает показать что-либо кому-либо."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"覚える":{"b":"覚える (おぼえる)","p":"v","m":{"az":"yadda saxlamaq; öyrənmək","en":"to memorize; to remember","ru":"запоминать; заучивать"},"n":{"az":"覚えました öyrəndim və ya yadda saxladım deməkdir.","en":"覚えました means memorized or learned.","ru":"覚えました означает запомнил или выучил."}},"親切":{"b":"親切 (しんせつ)","p":"an","m":{"az":"mehriban, xeyirxah","en":"kind, helpful","ru":"добрый, отзывчивый"},"n":{"az":"な-sifətdir: 親切な人 = mehriban insan.","en":"A na-adjective: 親切な人 = kind person.","ru":"な-прилагательное: 親切な人 = добрый человек."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"読む":{"b":"読む (よむ)","p":"v","m":{"az":"oxumaq","en":"to read","ru":"читать"},"n":{"az":"て forması 読んで-dir: 読んでください oxuyun, zəhmət olmasa deməkdir.","en":"The て-form is 読んで: 読んでください means please read.","ru":"Форма на て: 読んで; 読んでください означает «прочитайте, пожалуйста»."}},"買い物":{"b":"買い物 (かいもの)","p":"n","m":{"az":"alış-veriş","en":"shopping","ru":"покупки, шопинг"},"n":{"az":"買い物をする = alış-veriş etmək; 買い物に行く = alış-verişə getmək.","en":"買い物をする = to shop; 買い物に行く = to go shopping.","ru":"買い物をする = делать покупки; 買い物に行く = идти за покупками."}},"買う":{"b":"買う (かう)","p":"v","m":{"az":"almaq; satın almaq","en":"buy","ru":"покупать"},"n":{"az":"て forması 買って olur.","en":"Its て-form is 買って.","ru":"Форма на て: 買って."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"走る":{"b":"走る (はしる)","p":"v","m":{"az":"qaçmaq","en":"run","ru":"бежать"},"n":{"az":"る ilə bitsə də birinci qrup feldir; 走らせる qaçırmaq, 車を走らせる isə maşını sürmək deməkdir.","en":"Despite ending in る, it is a group 1 verb; 走らせる means make run, and 車を走らせる means drive a car.","ru":"Несмотря на る, это глагол первой группы; 走らせる означает заставить бежать, а 車を走らせる вести машину."}},"足":{"b":"足 (あし)","p":"n","m":{"az":"ayaq","en":"foot; leg","ru":"нога; ступня"},"n":{"az":"Kontekstdən asılı olaraq ayağın pəncəsini və ya bütün aşağı ətrafı bildirir.","en":"Can mean the foot or the whole leg, depending on context.","ru":"В зависимости от контекста обозначает ступню или всю ногу."}},"踊り方":{"b":"踊り方 (おどりかた)","p":"n","m":{"az":"rəqs etmə üsulu","en":"way of dancing; how to dance","ru":"способ танцевать"},"n":{"az":"踊る feilinin ます kökü olan 踊り sözünə 方 artırılır.","en":"方 is added to the ます-stem 踊り of 踊る.","ru":"方 добавляется к основе 踊り глагола 踊る."}},"踊る":{"b":"踊る (おどる)","p":"v","m":{"az":"rəqs etmək","en":"dance","ru":"танцевать"}},"軽い":{"b":"軽い (かるい)","p":"ai","m":{"az":"yüngül","en":"light, lightweight","ru":"лёгкий"},"n":{"az":"い-sifətdir; əksi 重い - ağır.","en":"An i-adjective; its opposite is 重い, heavy.","ru":"Это i-прилагательное; антоним 重い - тяжёлый."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"途中":{"b":"途中 (とちゅう)","p":"n","m":{"az":"yolun ortası; prosesin gedişi","en":"on the way; in the middle of something","ru":"по пути; в процессе"},"n":{"az":"〜の途中で quruluşu bir işin və ya yolun ortasında mənasını verir.","en":"〜の途中で means in the middle of an activity or journey.","ru":"〜の途中で означает в середине действия или пути."}},"連れる":{"b":"連れる (つれる)","p":"v","m":{"az":"özü ilə aparmaq, müşayiət etmək","en":"to take along, to accompany","ru":"брать с собой, вести"},"n":{"az":"連れて行く birini aparmaq, 連れて来る isə birini gətirmək deməkdir.","en":"連れて行く means to take someone along; 連れて来る means to bring someone.","ru":"連れて行く означает взять кого-то с собой, а 連れて来る означает привести кого-то."}},"遊ぶ":{"b":"遊ぶ (あそぶ)","p":"v","m":{"az":"oynamaq; əylənmək","en":"to play; to have fun","ru":"играть; развлекаться"},"n":{"az":"て-forması 遊んで-dir; 友達と遊ぶ = dostlarla oynamaq və ya vaxt keçirmək.","en":"Its て-form is 遊んで; 友達と遊ぶ means to play or spend time with friends.","ru":"て-форма: 遊んで; 友達と遊ぶ означает играть или проводить время с друзьями."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"遠い":{"b":"遠い (とおい)","p":"ai","m":{"az":"uzaq","en":"far, distant","ru":"далёкий"},"n":{"az":"い-sifətdir: 遠くない = uzaq deyil; 駅から遠い = stansiyadan uzaqdır.","en":"An i-adjective: 遠くない = not far; 駅から遠い = far from the station.","ru":"Прилагательное на い: 遠くない = недалеко; 駅から遠い = далеко от станции."}},"選び方":{"b":"選び方 (えらびかた)","p":"n","m":{"az":"seçmə üsulu, seçim qaydası","en":"how to choose, way of choosing","ru":"способ выбора"},"n":{"az":"選ぶ felinin ます kökü + 方 seçim üsulunu bildirir.","en":"The masu-stem of 選ぶ + 方 describes how to choose.","ru":"Основа формы ます глагола 選ぶ + 方 обозначает способ выбора."}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"鏡":{"b":"鏡 (かがみ)","p":"n","m":{"az":"güzgü","en":"mirror","ru":"зеркало"}},"間違える":{"b":"間違える (まちがえる)","p":"v","m":{"az":"səhv etmək, qarışdırmaq","en":"to make a mistake, to confuse","ru":"ошибаться, путать"},"n":{"az":"間違える təsirli feildir; 間違う da səhv etmək mənasında işlənir.","en":"間違える is transitive; 間違う can also mean to make a mistake.","ru":"間違える переходный глагол; 間違う также означает ошибаться."}},"降る":{"b":"降る (ふる)","p":"v","m":{"az":"yağmaq","en":"fall as rain or snow","ru":"идти о дожде или снеге"},"n":{"az":"Yağıntı が ilə göstərilir: 雨が降る, 雪が降る.","en":"Precipitation takes が: 雨が降る, 雪が降る.","ru":"Осадки оформляются が: 雨が降る, 雪が降る."}},"離れる":{"b":"離れる (はなれる)","p":"v","m":{"az":"uzaqlaşmaq, ayrılmaq","en":"to move away, to separate","ru":"отдаляться, отделяться"},"n":{"az":"〜から離れる bir yerdən uzaqlaşmaq, 離す isə bir şeyi ayırmaq deməkdir.","en":"〜から離れる means to move away from something, while 離す means to separate things.","ru":"〜から離れる означает отдаляться от чего-либо, а 離す - разделять предметы."}},"難しい":{"b":"難しい (むずかしい)","p":"ai","m":{"az":"çətin, mürəkkəb","en":"difficult, complicated","ru":"трудный, сложный"},"n":{"az":"い-sifətdir: 難しくない = çətin deyil.","en":"An i-adjective: 難しくない = not difficult.","ru":"Прилагательное на い: 難しくない = нетрудный."}},"雨":{"b":"雨 (あめ)","p":"n","m":{"az":"yağış","en":"rain","ru":"дождь"}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"音":{"b":"音 (おと)","p":"n","m":{"az":"səs (əşya səsi)","en":"sound","ru":"звук"},"n":{"az":"音がする = səs gəlmək. İnsan səsi üçün 声.","en":"音がする = a sound is heard. Human voice: 声.","ru":"音がする = слышен звук. Голос человека – 声."}},"音楽":{"b":"音楽 (おんがく)","p":"n","m":{"az":"musiqi","en":"music","ru":"музыка"}},"頼む":{"b":"頼む (たのむ)","p":"v","m":{"az":"xahiş etmək; sifariş vermək","en":"to request; to order","ru":"просить; заказывать"},"n":{"az":"頼みました keçmiş nəzakətli formadır.","en":"頼みました is the polite past form.","ru":"頼みました - вежливая форма прошедшего времени."}},"顔":{"b":"顔 (かお)","p":"n","m":{"az":"üz, sifət","en":"face","ru":"лицо"}},"食べる":{"b":"食べる (たべる)","p":"v","m":{"az":"yemək","en":"to eat","ru":"есть"}},"飲む":{"b":"飲む (のむ)","p":"v","m":{"az":"içmək","en":"drink","ru":"пить"},"n":{"az":"Dərman qəbul etmək üçün də işlənir: 薬を飲む.","en":"Also used for taking medicine: 薬を飲む.","ru":"Также употребляется для приёма лекарства: 薬を飲む."}}}};